/* ===========================================================================
 * EVO: UI navigation sounds.
 *
 * A tiny synthesised-tone engine on its own AudioOut port, deliberately
 * independent of the media audio path:
 *   - it must work in the menus, where no media port is open at all
 *   - it must never disturb playback timing, so it does not share the media
 *     port, its queue, or its clock
 *
 * The port is opened lazily on first use and left open. A dedicated thread
 * owns it, because sceAudioOutOutput blocks until the port accepts a block
 * (~5.3 ms per 256-frame grain) and the UI thread must not stall on that.
 *
 * Sounds are generated rather than loaded: a handful of short enveloped sine
 * blips cost nothing, need no asset files, and cannot fail to load.
 * ======================================================================== */

enum {
    EVO_SFX_NONE = 0,
    EVO_SFX_MOVE,      /* d-pad navigation      */
    EVO_SFX_CONFIRM,   /* cross / select        */
    EVO_SFX_BACK,      /* circle / cancel       */
    EVO_SFX_TOGGLE     /* option changed        */
};

#define EVO_SFX_GRAIN 256
#define EVO_SFX_RATE  48000

static volatile int  evo_sfx_pending = EVO_SFX_NONE;
static volatile int  evo_sfx_running = 0;
static int           evo_sfx_handle  = -1;
static pthread_t     evo_sfx_thread_id;
static int           evo_sfx_enabled = 1;

/* One blip: frequency sweep from f0 to f1 over `ms`, exponential decay.
 * The sweep is what makes these read as UI feedback rather than test tones. */
static void evo_sfx_render(int handle, double f0, double f1, int ms, double gain)
{
    int total = (EVO_SFX_RATE * ms) / 1000;
    int blocks = (total + EVO_SFX_GRAIN - 1) / EVO_SFX_GRAIN;
    int16_t buf[EVO_SFX_GRAIN * 2];
    double phase = 0.0;
    int n = 0;

    for (int b = 0; b < blocks; b++) {
        for (int i = 0; i < EVO_SFX_GRAIN; i++, n++) {
            double t   = (double)n / (double)total;
            if (t > 1.0) t = 1.0;

            double f   = f0 + (f1 - f0) * t;
            double env = exp(-4.5 * t) * (1.0 - t);   /* fast, clean decay */

            /* 2 ms attack ramp: a hard start clicks. */
            int attack = EVO_SFX_RATE / 500;
            if (n < attack)
                env *= (double)n / (double)attack;

            int16_t s = (int16_t)(sin(phase) * env * gain * 26000.0);
            phase += 2.0 * M_PI * f / (double)EVO_SFX_RATE;
            if (phase >= 2.0 * M_PI) phase -= 2.0 * M_PI;

            buf[i * 2 + 0] = s;
            buf[i * 2 + 1] = s;
        }
        if (sceAudioOutOutput(handle, buf) < 0)
            return;
    }

    /* One silent grain so the port does not repeat the tail. */
    memset(buf, 0, sizeof(buf));
    sceAudioOutOutput(handle, buf);
}

static void *evo_sfx_thread(void *arg)
{
    (void)arg;

    while (evo_sfx_running) {
        int want = evo_sfx_pending;

        if (want == EVO_SFX_NONE) {
            usleep(2000);
            continue;
        }
        evo_sfx_pending = EVO_SFX_NONE;

        if (evo_sfx_handle < 1)
            continue;

        switch (want) {
        case EVO_SFX_MOVE:    evo_sfx_render(evo_sfx_handle, 1180, 1180, 26, 0.30); break;
        case EVO_SFX_CONFIRM: evo_sfx_render(evo_sfx_handle,  760, 1520, 70, 0.42); break;
        case EVO_SFX_BACK:    evo_sfx_render(evo_sfx_handle,  760,  380, 70, 0.38); break;
        case EVO_SFX_TOGGLE:  evo_sfx_render(evo_sfx_handle,  980, 1360, 45, 0.36); break;
        default: break;
        }
    }
    return NULL;
}

static void evo_sfx_init(void)
{
    if (evo_sfx_running)
        return;

    sceAudioOutInit();

    evo_sfx_handle = sceAudioOutOpen(0xFF, 0, 0,
                                     EVO_SFX_GRAIN, EVO_SFX_RATE,
                                     1 /* S16_STEREO */);
    if (evo_sfx_handle < 1) {
        /* Not fatal - the UI simply stays silent. */
        evo_sfx_handle = -1;
        return;
    }

    evo_sfx_running = 1;
    if (pthread_create(&evo_sfx_thread_id, NULL, evo_sfx_thread, NULL) != 0) {
        evo_sfx_running = 0;
        sceAudioOutClose(evo_sfx_handle);
        evo_sfx_handle = -1;
    }
}

/* Non-blocking. Newer requests replace older ones: rapid d-pad scrolling
 * should feel responsive, not queue up a backlog of blips. */
static void evo_sfx_play(int kind)
{
    if (!evo_sfx_enabled || evo_sfx_handle < 1)
        return;
    evo_sfx_pending = kind;
}

