/* ===========================================================================
 * EVO: framebuffer screenshot.
 *
 * Press L3 to write the current frame to the USB stick. Written as a BMP
 * because it needs no encoder - the player links stb_image for *reading*, not
 * writing, and 6 MB of uncompressed pixels beats pulling in a PNG encoder for
 * a debugging aid.
 *
 * The point of this is to stop describing UI problems in prose. "The corners
 * look aliased" and "the corners are square because the radius argument is
 * discarded" are very different bug reports, and only a screenshot
 * distinguishes them.
 * ======================================================================== */
static int evo_screenshot_seq = 0;
static volatile int evo_screenshot_request = 0;

static int evo_screenshot_write(const uint32_t *fb, int w, int h)
{
    char path[256];
    FILE *f = NULL;

    if (!fb || w <= 0 || h <= 0)
        return -1;

    /* Find a free filename rather than overwriting. */
    for (int i = 0; i < 1000; i++) {
        snprintf(path, sizeof(path),
                 "/mnt/usb0/evo_shot_%03d.bmp", evo_screenshot_seq++);
        f = fopen(path, "rb");
        if (!f)
            break;
        fclose(f);
        f = NULL;
    }

    f = fopen(path, "wb");
    if (!f)
        return -1;

    const uint32_t row_bytes = (uint32_t)w * 3u;
    const uint32_t pad       = (4u - (row_bytes % 4u)) % 4u;
    const uint32_t img_bytes = (row_bytes + pad) * (uint32_t)h;
    const uint32_t file_size = 14u + 40u + img_bytes;

    unsigned char hdr[54];
    memset(hdr, 0, sizeof(hdr));
    hdr[0] = 'B'; hdr[1] = 'M';
    hdr[2]  = (unsigned char)(file_size      );
    hdr[3]  = (unsigned char)(file_size >>  8);
    hdr[4]  = (unsigned char)(file_size >> 16);
    hdr[5]  = (unsigned char)(file_size >> 24);
    hdr[10] = 54;                       /* pixel data offset */
    hdr[14] = 40;                       /* BITMAPINFOHEADER  */
    hdr[18] = (unsigned char)( w        );
    hdr[19] = (unsigned char)( w >>  8  );
    hdr[20] = (unsigned char)( w >> 16  );
    hdr[21] = (unsigned char)( w >> 24  );
    hdr[22] = (unsigned char)( h        );
    hdr[23] = (unsigned char)( h >>  8  );
    hdr[24] = (unsigned char)( h >> 16  );
    hdr[25] = (unsigned char)( h >> 24  );
    hdr[26] = 1;                        /* planes */
    hdr[28] = 24;                       /* bpp    */

    fwrite(hdr, 1, sizeof(hdr), f);

    /* BMP rows run bottom-up. Framebuffer is ABGR8888 (R in the low byte),
     * BMP wants B,G,R per pixel. */
    unsigned char *line = (unsigned char *)malloc(row_bytes + pad);
    if (!line) {
        fclose(f);
        return -1;
    }
    memset(line, 0, row_bytes + pad);

    for (int yy = h - 1; yy >= 0; yy--) {
        const uint32_t *src = &fb[(size_t)yy * (size_t)w];
        for (int xx = 0; xx < w; xx++) {
            uint32_t p = src[xx];
            line[xx * 3 + 0] = (unsigned char)((p >> 16) & 0xFF);  /* B */
            line[xx * 3 + 1] = (unsigned char)((p >>  8) & 0xFF);  /* G */
            line[xx * 3 + 2] = (unsigned char)( p        & 0xFF);  /* R */
        }
        fwrite(line, 1, row_bytes + pad, f);
    }

    free(line);
    fclose(f);
    return 0;
}


void rect(uint32_t *fb, int x, int y, int w, int h, uint32_t color) {
    for (int yy = y; yy < y + h; yy++) {
        for (int xx = x; xx < x + w; xx++) {
            if (xx >= 0 && xx < WIDTH && yy >= 0 && yy < HEIGHT) {
                fb[yy * WIDTH + xx] = color;
            }
        }
    }
}



int count_files_in_path(const char *path) {
    evo_dir_t *dir = evo_opendir(path);
    if (!dir) return -1;

    int count = 0;
    struct dirent *entry;

    while ((entry = evo_readdir(dir)) != NULL) {
        if (entry->d_name[0] == '.') continue;
        if (!strcmp(entry->d_name, "$RECYCLE.BIN")) continue;
        if (!strcmp(entry->d_name, "System Volume Information")) continue;
        count++;
    }

    evo_closedir(dir);
    return count;
}



int load_stb_image_file(const char *path) {
    int w, h, channels;
    unsigned char *data = stbi_load(path, &w, &h, &channels, 4);

    if (!data) {
        toast("IMAGE FAIL", "stbi_load failed");
        bmp_loaded = 0;
        return 0;
    }

    if (bmp_pixels) {
        free(bmp_pixels);
        bmp_pixels = NULL;
    }

    bmp_pixels = malloc(w * h * sizeof(uint32_t));
    if (!bmp_pixels) {
        stbi_image_free(data);
        toast("IMAGE FAIL", "Out of memory");
        bmp_loaded = 0;
        return 0;
    }

    for (int i = 0; i < w * h; i++) {
        unsigned char r = data[i * 4 + 0];
        unsigned char g = data[i * 4 + 1];
        unsigned char b = data[i * 4 + 2];
        bmp_pixels[i] = 0xFF000000 | (b << 16) | (g << 8) | r;
    }

    stbi_image_free(data);

    bmp_w = w;
    bmp_h = h;
    bmp_loaded = 1;

    toast("IMAGE LOADED", path);
    return 1;
}

int load_bmp_file(const char *path);
