/* ---------------------------------------------------------------------------
 * OSD theme colour helpers. (The rest of PROSPERO_PLAYER_OSD_MODULE — the SDF
 * scrub preview / handle / capture — was dead after the RmlUi playback OSD
 * landed and has been removed. These two are still used by the music
 * visualiser and the remaining SDF screen chrome.)
 * ------------------------------------------------------------------------ */
static uint32_t osd_col(uint32_t colour, int alpha)
{
    if (alpha < 0)   alpha = 0;
    if (alpha > 255) alpha = 255;
    return (colour & 0x00FFFFFFu) | ((uint32_t)alpha << 24);
}



/*
 * Subtitle overlay renderer + its two face-aware helpers. Stayed in main.c
 * when the subtitle engine moved to media/evo_subtitle.c (A4): they are welded
 * to the font-atlas headers, rr_text and the EVO_FACE_* enum. The cue lookup
 * and embedded-text-at helpers they call live in the module (evo_subtitle.h).
 */


static int prospero_subtitle_wrap_text(
    const char *text,
    char lines[
        PROSPERO_SUBTITLE_MAX_LINES
    ][
        PROSPERO_SUBTITLE_LINE_SIZE
    ]
) {
    int line_count = 0;
    const char *cursor = text;
    int max_wrap_len = (prospero_subtitle_face == EVO_FACE_SUB)   ? 48 :
                       (prospero_subtitle_face == EVO_FACE_TITLE) ? 26 : 36;
    int min_break_len = max_wrap_len / 2;

    while (
        cursor &&
        *cursor &&
        line_count <
            PROSPERO_SUBTITLE_MAX_LINES
    ) {
        while (*cursor == ' ') {
            cursor++;
        }

        if (*cursor == '\n') {
            cursor++;
            continue;
        }

        if (!*cursor) {
            break;
        }

        int length = 0;
        int last_space = -1;

        while (
            cursor[length] &&
            cursor[length] != '\n' &&
            length < max_wrap_len
        ) {
            if (cursor[length] == ' ') {
                last_space = length;
            }

            length++;
        }

        if (
            cursor[length] &&
            cursor[length] != '\n' &&
            length >= max_wrap_len &&
            last_space > min_break_len
        ) {
            length = last_space;
        }

        if (length <= 0) {
            cursor++;
            continue;
        }

        int copy_length =
            length;

        if (
            copy_length >=
            PROSPERO_SUBTITLE_LINE_SIZE
        ) {
            copy_length =
                PROSPERO_SUBTITLE_LINE_SIZE - 1;
        }

        memcpy(
            lines[line_count],
            cursor,
            copy_length
        );

        lines[line_count][copy_length] = 0;
        prospero_subtitle_trim(
            lines[line_count]
        );

        if (lines[line_count][0]) {
            line_count++;
        }

        cursor += length;

        while (*cursor == ' ') {
            cursor++;
        }

        if (*cursor == '\n') {
            cursor++;
        }
    }

    if (
        cursor &&
        *cursor &&
        line_count ==
            PROSPERO_SUBTITLE_MAX_LINES
    ) {
        char *last =
            lines[
                PROSPERO_SUBTITLE_MAX_LINES - 1
            ];

        size_t length =
            strlen(last);

        if (
            length + 3 <
            PROSPERO_SUBTITLE_LINE_SIZE
        ) {
            strcat(last, "...");
        }
    }

    return line_count;
}

/*
 * Measure subtitle line width with the glyph advances matching the active subtitle face.
 */
static int prospero_subtitle_text_width(
    const char *text
) {
    return evo_font_text_width(text, prospero_subtitle_face);
}


static void prospero_subtitle_draw(
    uint32_t *framebuffer,
    double position,
    int osd_visibility
) {
    if (
        !framebuffer ||
        !prospero_subtitle_enabled
    ) {
        return;
    }

    /* Apply user subtitle delay (positive = subs later) */
    double sub_pos =
        position - ((double)prospero_subtitle_delay_ms / 1000.0);

    const char *active_text = NULL;

    char embedded_text[
        PROSPERO_EMBEDDED_SUBTITLE_TEXT_SIZE
    ] = {0};

    if (prospero_subtitle_use_external) {
        const ProsperoSubtitleCue *cue =
            prospero_subtitle_active_cue(
                sub_pos
            );

        if (cue) {
            active_text =
                cue->text;
        }
    } else if (
        prospero_embedded_subtitle_text_at(
            sub_pos,
            embedded_text,
            sizeof(embedded_text)
        )
    ) {
        active_text =
            embedded_text;
    }

    if (
        !active_text ||
        !active_text[0]
    ) {
        return;
    }

    char lines[
        PROSPERO_SUBTITLE_MAX_LINES
    ][
        PROSPERO_SUBTITLE_LINE_SIZE
    ] = {{0}};

    int line_count =
        prospero_subtitle_wrap_text(
            active_text,
            lines
        );

    if (line_count <= 0) {
        return;
    }

    /*
     * Subtitles move upward while the playback OSD is displayed.
     */
    int bottom_y =
        osd_visibility > 0
            ? 625
            : 910;

    int line_spacing =
        (prospero_subtitle_face == EVO_FACE_SUB)   ? 56 :
        (prospero_subtitle_face == EVO_FACE_TITLE) ? 96 : 76;

    int first_y =
        bottom_y -
        (line_count - 1) *
            line_spacing;

    for (
        int index = 0;
        index < line_count;
        index++
    ) {
        const char *line =
            lines[index];

        int text_width =
            prospero_subtitle_text_width(
                line
            );

        /*
         * Exact horizontal center.
         */
        int x =
            (WIDTH - text_width) / 2;
        if (x < 0)
            x = 0;

        int y =
            first_y +
            index * line_spacing;

        /*
         * Soft lower shadow (symmetric-ish so it doesn't pull center).
         */
        rr_text(
            framebuffer,
            x + 2,
            y + 3,
            line,
            RR_BGRA(
                0,
                0,
                0,
                190
            ),
            prospero_subtitle_face
        );

        /*
         * Thin outline around the letters. No background rectangle.
         */
        rr_text(
            framebuffer,
            x - 2,
            y,
            line,
            RR_BGRA(
                0,
                0,
                0,
                245
            ),
            prospero_subtitle_face
        );

        rr_text(
            framebuffer,
            x + 2,
            y,
            line,
            RR_BGRA(
                0,
                0,
                0,
                245
            ),
            prospero_subtitle_face
        );

        rr_text(
            framebuffer,
            x,
            y - 2,
            line,
            RR_BGRA(
                0,
                0,
                0,
                245
            ),
            prospero_subtitle_face
        );

        rr_text(
            framebuffer,
            x,
            y + 2,
            line,
            RR_BGRA(
                0,
                0,
                0,
                245
            ),
            prospero_subtitle_face
        );

        /*
         * Main subtitle text.
         */
        rr_text(
            framebuffer,
            x,
            y,
            line,
            RR_BGRA(
                250,
                252,
                255,
                255
            ),
            prospero_subtitle_face
        );
    }
}











/* ==========================================================================
 * Subtitle track picker
 *
 * A retail rip carries thirty-odd subtitle tracks, and the container's own
 * metadata is not trustworthy about which one is worth watching - the file
 * that prompted this flags a two-cue vanity track as the default English
 * one. So the choice is offered, with the fact that settles it - how many
 * cues each track declares - shown next to each.
 * ========================================================================== */

#define EVO_SUBS_MAX 64

static evo_focus evo_subs_focus;
static int       evo_subs_tracks[EVO_SUBS_MAX];   /* -2 off, -1 external SRT */
static char      evo_subs_labels[EVO_SUBS_MAX][40];
static char      evo_subs_details[EVO_SUBS_MAX][20];
static int       evo_subs_weak[EVO_SUBS_MAX];
static int       evo_subs_count;

/*
 * ISO 639-2 to something the font atlas can actually draw.
 *
 * The atlas holds A-Z a-z 0-9 and a little punctuation - no accents, no
 * parentheses - so a track titled "Espanol (Espana)" with the accents it
 * really carries would render as a row of holes. Track titles are therefore
 * never drawn directly; the language code picks an ASCII name instead.
 */
static const char *prospero_subtitle_language_name(const char *code)
{
    static const struct { const char *code; const char *name; } table[] = {
        { "eng", "ENGLISH"    }, { "ara", "ARABIC"     },
        { "cze", "CZECH"      }, { "ces", "CZECH"      },
        { "dan", "DANISH"     }, { "ger", "GERMAN"     },
        { "deu", "GERMAN"     }, { "gre", "GREEK"      },
        { "ell", "GREEK"      }, { "spa", "SPANISH"    },
        { "fin", "FINNISH"    }, { "fil", "FILIPINO"   },
        { "fre", "FRENCH"     }, { "fra", "FRENCH"     },
        { "heb", "HEBREW"     }, { "hin", "HINDI"      },
        { "hun", "HUNGARIAN"  }, { "ind", "INDONESIAN" },
        { "ita", "ITALIAN"    }, { "jpn", "JAPANESE"   },
        { "kor", "KOREAN"     }, { "may", "MALAY"      },
        { "msa", "MALAY"      }, { "nob", "NORWEGIAN"  },
        { "nor", "NORWEGIAN"  }, { "dut", "DUTCH"      },
        { "nld", "DUTCH"      }, { "pol", "POLISH"     },
        { "por", "PORTUGUESE" }, { "rum", "ROMANIAN"   },
        { "ron", "ROMANIAN"   }, { "rus", "RUSSIAN"    },
        { "swe", "SWEDISH"    }, { "tam", "TAMIL"      },
        { "tel", "TELUGU"     }, { "tha", "THAI"       },
        { "tur", "TURKISH"    }, { "chi", "CHINESE"    },
        { "zho", "CHINESE"    }, { "vie", "VIETNAMESE" },
        { "ukr", "UKRAINIAN"  }, { "bul", "BULGARIAN"  },
        { "hrv", "CROATIAN"   }, { "srp", "SERBIAN"    },
        { "slo", "SLOVAK"     }, { "slv", "SLOVENIAN"  },
        { "est", "ESTONIAN"   }, { "lav", "LATVIAN"    },
        { "lit", "LITHUANIAN" }, { "isl", "ICELANDIC"  }
    };

    if (!code || !code[0]) {
        return NULL;
    }

    for (
        size_t i = 0;
        i < sizeof(table) / sizeof(table[0]);
        i++
    ) {
        if (strcasecmp(code, table[i].code) == 0) {
            return table[i].name;
        }
    }

    return NULL;
}


/*
 * Does the title carry a qualifier worth showing? SDH and FORCED change what
 * you actually get; the rest of a title is usually the release group
 * advertising itself.
 */
static const char *prospero_subtitle_qualifier(AVStream *stream)
{
    AVDictionaryEntry *title;

    if (!stream) {
        return "";
    }

    if (stream->disposition & AV_DISPOSITION_FORCED) {
        return " FORCED";
    }

    if (stream->disposition & AV_DISPOSITION_HEARING_IMPAIRED) {
        return " SDH";
    }

    title =
        av_dict_get(
            stream->metadata,
            "title",
            NULL,
            0
        );

    if (title && title->value) {
        if (str_contains_ci(title->value, "SDH"))    return " SDH";
        if (str_contains_ci(title->value, "FORCED")) return " FORCED";
        if (str_contains_ci(title->value, "SIGNS"))  return " SIGNS";
    }

    return "";
}


/*
 * Rebuild the track list. Cheap enough to run every frame the picker is
 * open, and doing it there rather than once on open means it cannot go
 * stale against a file that was swapped underneath it.
 */
static void evo_subs_sync(void)
{
    int count = 0;

    /*
     * "Off" is always first: it is the one entry that always works, and the
     * only way back once subtitles are on.
     */
    evo_subs_tracks[count] = -2;
    snprintf(evo_subs_labels[count], sizeof(evo_subs_labels[0]),
             "SUBTITLES OFF");
    evo_subs_details[count][0] = 0;
    evo_subs_weak[count] = 0;
    count++;

    if (prospero_subtitle_count > 0 && count < EVO_SUBS_MAX) {
        evo_subs_tracks[count] = -1;
        snprintf(evo_subs_labels[count], sizeof(evo_subs_labels[0]),
                 "EXTERNAL SRT");
        snprintf(evo_subs_details[count], sizeof(evo_subs_details[0]),
                 "%d CUES", prospero_subtitle_count);
        evo_subs_weak[count] = 0;
        count++;
    }

    for (
        unsigned int index = 0;
        play_fmt && index < play_fmt->nb_streams && count < EVO_SUBS_MAX;
        index++
    ) {
        AVStream *stream = play_fmt->streams[index];
        AVDictionaryEntry *language;
        const char *name;
        char base[40];
        int cues;
        int dup = 0;

        if (
            !stream ||
            !stream->codecpar ||
            stream->codecpar->codec_type != AVMEDIA_TYPE_SUBTITLE ||
            !prospero_embedded_subtitle_supported(
                stream->codecpar->codec_id
            )
        ) {
            continue;
        }

        language =
            av_dict_get(
                stream->metadata,
                "language",
                NULL,
                0
            );

        name =
            prospero_subtitle_language_name(
                language ? language->value : NULL
            );

        if (name) {
            snprintf(base, sizeof(base), "%s%s", name,
                     prospero_subtitle_qualifier(stream));
        } else {
            /* An unmapped code still identifies the track, which beats
             * showing a row with no name on it. */
            snprintf(base, sizeof(base), "TRACK %u%s", index,
                     prospero_subtitle_qualifier(stream));
        }

        /*
         * Two tracks of one language are common - Spanish for Spain and for
         * Latin America - and the part of the title that tells them apart is
         * exactly the part the atlas cannot draw. Number them rather than
         * showing two identical rows.
         */
        for (int i = 0; i < count; i++) {
            if (strncmp(evo_subs_labels[i], base, sizeof(base)) == 0) {
                dup++;
            }
        }

        if (dup > 0) {
            snprintf(evo_subs_labels[count], sizeof(evo_subs_labels[0]),
                     "%s %d", base, dup + 1);
        } else {
            snprintf(evo_subs_labels[count], sizeof(evo_subs_labels[0]),
                     "%s", base);
        }

        cues = prospero_subtitle_declared_cues(stream);

        if (cues < 0) {
            evo_subs_details[count][0] = 0;
            evo_subs_weak[count] = 0;
        } else if (cues < PROSPERO_SUBTITLE_MIN_USEFUL_CUES) {
            snprintf(evo_subs_details[count], sizeof(evo_subs_details[0]),
                     "SIGNS ONLY");
            evo_subs_weak[count] = 1;
        } else {
            snprintf(evo_subs_details[count], sizeof(evo_subs_details[0]),
                     "%d CUES", cues);
            evo_subs_weak[count] = 0;
        }

        evo_subs_tracks[count] = (int)index;
        count++;
    }

    evo_subs_count = count;

    evo_subs_focus.visible = evo_screen_picker_capacity();
    evo_subs_focus.wrap    = 1;

    evo_focus_set_count(
        &evo_subs_focus,
        count
    );
}


static void prospero_settings_save(void);

static void draw_subtitle_picker(uint32_t *fb)
{
    int cap = evo_screen_picker_capacity();
    int first;
    int shown;
    int active;

    evo_subs_sync();

    first = evo_subs_focus.scroll;
    shown = evo_subs_count - first;

    if (shown > cap) {
        shown = cap;
    }

    /* Never past the RmlUi params' fixed track array (8). */
    if (shown > 8) {
        shown = 8;
    }

    if (shown < 0) {
        shown = 0;
    }

    /* What is playing right now, in the same -2 / -1 / index space. */
    active =
        !prospero_subtitle_enabled
            ? -2
            : prospero_subtitle_use_external
                  ? -1
                  : prospero_embedded_subtitle_stream_index;

    const char *size_str =
        prospero_subtitle_face == EVO_FACE_SUB   ? "SMALL" :
        prospero_subtitle_face == EVO_FACE_TITLE ? "LARGE" : "MEDIUM";

    int pface = (prospero_subtitle_face == EVO_FACE_SUB) ? 0 :
                ((prospero_subtitle_face == EVO_FACE_TITLE) ? 2 : 1);

    if (!evo_rmlui_is_initialized()) return;

    evo_rmlui_subtitles_params_t p;
    memset(&p, 0, sizeof(p));
    p.eyebrow = "SUBTITLES & CLOSED CAPTIONS";
    p.title = "SELECT SUBTITLE TRACK";
    p.size_str = size_str;
    p.preview_text = "Welcome to EVO Player on PlayStation 5";
    p.preview_face = pface;
    p.track_count = shown;

    for (int i = 0; i < shown; i++) {
        p.tracks[i].label = evo_subs_labels[first + i];
        p.tracks[i].detail = evo_subs_details[first + i];
        p.tracks[i].is_current = (evo_subs_tracks[first + i] == active);
        p.tracks[i].is_focused = ((first + i) == evo_subs_focus.index);
    }

    evo_rmlui_update_subtitles(&p);
    evo_rmlui_render_subtitles(fb, WIDTH, HEIGHT);
}


static void evo_subs_cycle_size(void)
{
    static const int order[3] = { EVO_FACE_SUB, EVO_FACE_MENU, EVO_FACE_TITLE };
    int i;

    for (i = 0; i < 3; i++) {
        if (order[i] == prospero_subtitle_face)
            break;
    }

    prospero_subtitle_face = order[(i + 1) % 3];
    prospero_settings_save();
    evo_feedback(EVO_FB_OPEN);

    toast("SUBTITLE SIZE",
          prospero_subtitle_face == EVO_FACE_SUB   ? "SMALL" :
          prospero_subtitle_face == EVO_FACE_TITLE ? "LARGE" : "MEDIUM");
}

static void evo_subs_step_size(int delta)
{
    static const int order[3] = { EVO_FACE_SUB, EVO_FACE_MENU, EVO_FACE_TITLE };
    int i;

    for (i = 0; i < 3; i++) {
        if (order[i] == prospero_subtitle_face)
            break;
    }

    int next = (i + delta) % 3;
    if (next < 0) next += 3;

    prospero_subtitle_face = order[next];
    prospero_settings_save();
    evo_feedback(EVO_FB_OPEN);

    toast("SUBTITLE SIZE",
          prospero_subtitle_face == EVO_FACE_SUB   ? "SMALL" :
          prospero_subtitle_face == EVO_FACE_TITLE ? "LARGE" : "MEDIUM");
}


static void evo_subs_open(void)
{
#if PP_BACKEND_ENABLED
    pp_product_overlay_enter();
#endif
    evo_subs_sync();

    /* Open on whatever is playing, not on row zero - the list is long and
     * landing on "off" every time invites turning them off by accident. */
    {
        int active =
            !prospero_subtitle_enabled
                ? -2
                : prospero_subtitle_use_external
                      ? -1
                      : prospero_embedded_subtitle_stream_index;

        for (int i = 0; i < evo_subs_count; i++) {
            if (evo_subs_tracks[i] == active) {
                evo_focus_set(&evo_subs_focus, i);
                break;
            }
        }
    }

    screen = SCREEN_SUBTITLE_PICKER;
}


static void evo_subs_activate(void)
{
    int track;

    if (
        evo_subs_focus.index < 0 ||
        evo_subs_focus.index >= evo_subs_count
    ) {
        return;
    }

    track = evo_subs_tracks[evo_subs_focus.index];

#if PP_BACKEND_ENABLED
    pp_product_overlay_leave();
#endif
    screen = SCREEN_PLAYER;

    /*
     * Turning subtitles off needs no reopen, and reopening for it would put
     * a visible hitch on the one action that should feel instant.
     */
    if (track == -2) {
        prospero_subtitle_enabled = 0;
        toast("SUBTITLES", "OFF");
        controls_last_used_ms = now_ms();
        return;
    }

    prospero_subtitle_apply_track(track);
}


/* Rail focus is a property of the shell, not of any one screen: pressing
 * LEFT out of a list should reach the rail from every section. Declared here
 * rather than beside the other shell state because the reader, which is
 * above that point in the file, draws with them. */
static int evo_rail_focused;
static int evo_rail_index;

/* ==========================================================================
 * TEXT READER
 *
 * The document, the wrapping and the scroll position live in
 * media/evo_textreader.c; this is the part that has to know about the player -
 * which button does what, where to go on Back, and how to phrase the header.
 *
 * Opening a text file used to do nothing at all: the browser listed .txt and
 * .srt, let you select them, and CROSS was silently ignored.
 * ======================================================================== */

static evo_text_doc g_reader_doc;
static int          g_reader_return_screen = SCREEN_USB_BROWSER;

/* The reader measures with the same tables rr_text draws with. Anything else
 * and the wrap would disagree with the rendering by a few pixels a line,
 * which shows up as the last word of long lines clipping. */
static int reader_measure(const char *s, int len, int face)
{
    int w = 0;
    int i;

    for (i = 0; i < len; i++)
        w += evo_font_advance(s[i], face);
    return w;
}

/* Extensions the reader will open. Subtitles are here because the player
 * already parses them for playback and being able to look at one before
 * committing to a film is genuinely useful. */
static int evo_is_text_file(const char *name)
{
    return has_ext(name, ".txt") || has_ext(name, ".log") ||
           has_ext(name, ".md")  || has_ext(name, ".srt") ||
           has_ext(name, ".vtt") || has_ext(name, ".ass") ||
           has_ext(name, ".ssa") || has_ext(name, ".nfo") ||
           has_ext(name, ".ini") || has_ext(name, ".cfg") ||
           has_ext(name, ".json") || has_ext(name, ".csv");
}

static int evo_reader_capacity(void)
{
    return evo_screen_reader_capacity(g_reader_doc.face);
}

static void evo_reader_open(const char *path)
{
    evo_text_free(&g_reader_doc);

    g_reader_return_screen = screen;
    evo_text_load(&g_reader_doc, path);

    if (g_reader_doc.status == EVO_TEXT_OK)
        evo_text_wrap(&g_reader_doc, evo_screen_reader_wrap_w(), reader_measure);

    screen = SCREEN_TEXT_READER;
    evo_feedback(EVO_FB_CONFIRM);
}

static void evo_reader_close(void)
{
    evo_text_free(&g_reader_doc);
    screen = g_reader_return_screen ? g_reader_return_screen : SCREEN_USB_BROWSER;
}

/* TRIANGLE cycles the reading size. Wrapping is redone at the new size and
 * evo_text_wrap keeps the top of the view on the same words, so changing size
 * does not lose your place - which is the whole reason anyone changes it
 * mid-document. */
static void evo_reader_cycle_face(void)
{
    static const int order[3] = { EVO_FACE_SMALL, EVO_FACE_SUB, EVO_FACE_MENU };
    int i;

    for (i = 0; i < 3; i++)
        if (order[i] == g_reader_doc.face)
            break;

    g_reader_doc.face = order[(i + 1) % 3];
    evo_text_wrap(&g_reader_doc, evo_screen_reader_wrap_w(), reader_measure);

    toast("TEXT SIZE",
          g_reader_doc.face == EVO_FACE_SMALL ? "SMALL" :
          g_reader_doc.face == EVO_FACE_SUB   ? "MEDIUM" : "LARGE");
}

static const char *evo_reader_notice(void)
{
    switch (g_reader_doc.status) {
    case EVO_TEXT_ERR_OPEN:   return "COULD NOT OPEN THIS FILE";
    case EVO_TEXT_ERR_EMPTY:  return "THIS FILE IS EMPTY";
    case EVO_TEXT_ERR_MEMORY: return "NOT ENOUGH MEMORY TO READ THIS FILE";
    case EVO_TEXT_ERR_BINARY: return "THIS IS NOT A TEXT FILE";
    default: break;
    }
    return g_reader_doc.line_count ? NULL : "NOTHING TO SHOW";
}

/* Defined later in this file, alongside the rest of the nav-rail sync
 * plumbing; forward-declared here since the reader screen is drawn earlier
 * in the file than that section. */
void evo_sync_rmlui_nav(int section, int rail_focused, int rail_index, int visible);

/*
 * Draw one evo_reader_model through RmlUi. Returns 1 when it handled the
 * frame, 0 when RmlUi is not up and the caller should fall back to the
 * immediate-mode renderer.
 */
static int evo_rmlui_draw_reader(uint32_t *fb, const evo_reader_model *m)
{
    evo_rmlui_reader_params_t p;
    int i;

    if (!evo_rmlui_is_initialized()) return 0;

    memset(&p, 0, sizeof(p));
    p.title        = m->title;
    p.subtitle     = m->subtitle;
    p.badge        = m->badge;
    p.rail_focused = evo_rail_focused;
    p.face         = m->face;
    p.progress     = m->progress;
    p.visible_frac = m->visible_frac;
    p.notice       = m->notice;
    p.footnote     = m->footnote;

    p.line_count = m->line_count;
    if (p.line_count > EVO_RMLUI_READER_LINES) p.line_count = EVO_RMLUI_READER_LINES;
    for (i = 0; i < p.line_count; i++)
        p.lines[i] = m->lines[i];

    evo_rmlui_update_reader(&p);
    evo_sync_rmlui_nav(EVO_SECTION_BROWSER, evo_rail_focused, evo_rail_index, 1);
    evo_rmlui_render_reader(fb, WIDTH, HEIGHT);
    return 1;
}

void draw_text_reader_screen(uint32_t *fb)
{
    static char  buf[EVO_READER_MAX_VISIBLE][512];
    const char  *win[EVO_READER_MAX_VISIBLE];
    char         badge[64];
    char         sub[192];
    char         foot[128];
    evo_reader_model m;
    int cap, shown, i;

    /* The window may need rebuilding after a resolution or rail change. */
    if (g_reader_doc.status == EVO_TEXT_OK)
        evo_text_wrap(&g_reader_doc, evo_screen_reader_wrap_w(), reader_measure);

    cap = evo_reader_capacity();
    shown = g_reader_doc.line_count - g_reader_doc.top;
    if (shown > cap) shown = cap;
    if (shown < 0) shown = 0;

    for (i = 0; i < shown; i++) {
        const evo_text_line *ln = &g_reader_doc.lines[g_reader_doc.top + i];
        int n = ln->len;

        if (n > (int)sizeof(buf[0]) - 1)
            n = (int)sizeof(buf[0]) - 1;
        memcpy(buf[i], ln->begin, (size_t)n);
        buf[i][n] = 0;
        win[i] = buf[i];
    }

    memset(&m, 0, sizeof(m));
    m.title  = g_reader_doc.title[0] ? g_reader_doc.title : "TEXT";
    m.notice = evo_reader_notice();

    if (!m.notice) {
        snprintf(badge, sizeof(badge), "LINE %d OF %d",
                 g_reader_doc.lines[g_reader_doc.top].source_line,
                 g_reader_doc.source_lines);
        m.badge = badge;
    }

    {
        const char *slash = strrchr(g_reader_doc.path, '/');
        snprintf(sub, sizeof(sub), "%.*s",
                 slash ? (int)(slash - g_reader_doc.path) : 0,
                 g_reader_doc.path);
        m.subtitle = sub[0] ? sub : NULL;
    }

    if (g_reader_doc.truncated) {
        /* Say it rather than letting the file appear to end early. */
        snprintf(foot, sizeof(foot),
                 "SHOWING THE FIRST %u KB OF %u KB",
                 (unsigned)(EVO_TEXT_MAX_BYTES / 1024u),
                 (unsigned)(g_reader_doc.file_bytes / 1024u));
        m.footnote = foot;
    }

    m.lines        = win;
    m.line_count   = shown;
    m.face         = g_reader_doc.face;
    m.line_pitch   = evo_screen_reader_pitch(g_reader_doc.face);
    m.progress     = evo_text_progress(&g_reader_doc, cap);
    m.visible_frac = g_reader_doc.line_count
                     ? (double)cap / (double)g_reader_doc.line_count : 1.0;

    evo_rmlui_draw_reader(fb, &m);
}

void draw_player_screen(uint32_t *fb) {
    const evo_theme *th = evo_theme_current();
    static int osd_visibility = 0;
    static int music_pulse = 0;

    /*
     * Video: paint decoded frame. Music: now-playing visualizer UI.
     *
     * No clear before the video draw. draw_video_frame_to_fb defines every
     * pixel itself, so clearing here wrote all 2M pixels black and then had
     * every one of them overwritten by the frame on the very next line: 8 MB
     * a frame, ~500 MB/s of memory traffic at 60fps, for nothing.
     */
    if (!prospero_music_mode) {
        draw_video_frame_to_fb(
            fb,
            0,
            0,
            WIDTH,
            HEIGHT
        );
    } else {
        /* The visualiser paints panels over a background, not a full opaque
         * cover, so this one still needs the ground beneath it. */
        for (int i = 0; i < WIDTH * HEIGHT; i++) {
            fb[i] = 0xFF000000;
        }

        music_pulse = (music_pulse + 1) % 360;
        /* Atmosphere */
        rr_fill(fb, 0, 0, 1920, 1080, osd_col(th->bg_top, 255));
        rr_fill(fb, 0, 0, 1920, 1080,
                osd_col(th->accent_soft, 40 + (music_pulse % 40)));

        rr_fill(fb, 82, 74, 5, 76, osd_col(th->accent, 225));
        rr_fill(fb, 82, 146, 31, 2, osd_col(th->accent, 195));
        rr_text(fb, 122, 70, "NOW PLAYING", osd_col(th->text_primary, 240), 3);
        rr_text(fb, 124, 132, "MUSIC", osd_col(th->accent, 225), 1);

        /* Center card */
        ui_round_asset(
            fb, 460, 220, 1000, 420, 28,
            osd_col(th->surface, 230),
            osd_col(th->accent, 160),
            osd_col(th->accent_soft, 50)
        );

        rr_fill(fb, 520, 280, 64, 64, osd_col(th->accent, 200));
        rr_text(fb, 620, 290, "EVO MUSIC", osd_col(th->accent, 235), 2);
        rr_text(
            fb, 620, 350,
            player_paused ? "PAUSED" : "PLAYING",
            osd_col(th->text_primary, 235),
            2
        );

        {
            char codec_line[96];
            const char *cname = "AUDIO";
            if (audio_ctx && audio_ctx->codec)
                cname = audio_ctx->codec->name ? audio_ctx->codec->name : "AUDIO";
            snprintf(
                codec_line, sizeof(codec_line),
                "%s  ·  CROSS PAUSE  ·  L/R SEEK",
                cname
            );
            rr_text(fb, 620, 420, codec_line, osd_col(th->text_secondary, 220), 1);
        }

        /* Simple pulse bars */
        for (int b = 0; b < 24; b++) {
            int h = 20 + ((music_pulse + b * 11) % 80);
            if (player_paused)
                h = 24;
            rr_fill(
                fb,
                520 + b * 36,
                560 - h,
                22,
                h,
                /* Bars shimmer by alpha rather than by hue, so the
                 * visualiser follows the theme instead of always being
                 * cyan. */
                osd_col(th->accent, 150 + (b % 4) * 25)
            );
        }
    }

    long long now = now_ms();

    int wants_controls =
        prospero_music_mode ||
        ((now - controls_last_used_ms < 3500)
        || player_paused
        || show_stats_for_nerds)
        || prospero_scrub_active;

    /*
     * Smooth OSD entrance and disappearance.
     */
    if (wants_controls) {
        if (osd_visibility < 255) {
            osd_visibility += 42;

            if (osd_visibility > 255) {
                osd_visibility = 255;
            }
        }
    } else {
        if (osd_visibility > 0) {
            osd_visibility -= 28;

            if (osd_visibility < 0) {
                osd_visibility = 0;
            }
        }
    }


    double position =
        resume_base_offset_seconds +
        prospero_media_clock_seconds();

    if (position < 0.0) {
        position = 0.0;
    }

    double display_position =
        prospero_scrub_active
            ? prospero_scrub_target
            : position;

    if (display_position < 0.0) {
        display_position = 0.0;
    }

double percentage = 0.0;

    if (media_duration_sec > 0.1) {
        percentage =
            display_position / media_duration_sec;

        if (percentage < 0.0) {
            percentage = 0.0;
        }

        if (percentage > 1.0) {
            percentage = 1.0;
        }
    }

    char title[160];
    char metadata[160];

    title[0] = 0;
    metadata[0] = 0;

    clean_media_title(
        current_media_path,
        title,
        sizeof(title),
        metadata,
        sizeof(metadata)
    );

    /* No length cap here any more: the RmlUi OSD marquees a long title
     * (#media-title) and ellipsises a long metadata line (#media-meta in
     * playback.rcss) itself. Pre-truncating hid the tail the marquee exists
     * to reveal (#16 / #44). */

    if (osd_visibility > 0) {
        int alpha = osd_visibility;

        char res_badge[32] = "";
        char hdr_badge[32] = "";
        char codec_badge[32] = "";
        char fps_badge[32] = "";
        char audio_badge[32] = "";

        if (g_vdec) {
            int vc_w = evo_vdec_ffmpeg_width(g_vdec);
            int vc_h = evo_vdec_ffmpeg_height(g_vdec);
            int vc_trc = evo_vdec_ffmpeg_color_trc(g_vdec);
            int vc_pf = evo_vdec_ffmpeg_pix_fmt(g_vdec);

            if (vc_w >= 3840 || vc_h >= 2160) {
                snprintf(res_badge, sizeof(res_badge), "4K UHD");
            } else if (vc_w >= 1920 || vc_h >= 1080) {
                snprintf(res_badge, sizeof(res_badge), "1080p FHD");
            } else if (vc_w >= 1280 || vc_h >= 720) {
                snprintf(res_badge, sizeof(res_badge), "720p HD");
            } else if (vc_h > 0) {
                snprintf(res_badge, sizeof(res_badge), "%dp", vc_h);
            }

            if (vc_trc == AVCOL_TRC_SMPTE2084) {
                snprintf(hdr_badge, sizeof(hdr_badge), "HDR10");
            } else if (vc_trc == AVCOL_TRC_ARIB_STD_B67) {
                snprintf(hdr_badge, sizeof(hdr_badge), "HLG");
            } else if (vc_trc == AVCOL_TRC_BT2020_10) {
                snprintf(hdr_badge, sizeof(hdr_badge), "HDR");
            }

            int is_10bit = 0;
            if (vc_pf == AV_PIX_FMT_YUV420P10LE ||
                vc_pf == AV_PIX_FMT_YUV420P10BE ||
                vc_pf == AV_PIX_FMT_YUV422P10LE ||
                vc_pf == AV_PIX_FMT_YUV444P10LE) {
                is_10bit = 1;
            }

            const char *cname = evo_vdec_ffmpeg_codec_name(g_vdec);
            if (cname[0]) {
                if (strcasecmp(cname, "hevc") == 0 || strcasecmp(cname, "h265") == 0) {
                    snprintf(codec_badge, sizeof(codec_badge), is_10bit ? "HEVC 10-BIT" : "HEVC");
                } else if (strcasecmp(cname, "h264") == 0 || strcasecmp(cname, "avc") == 0) {
                    snprintf(codec_badge, sizeof(codec_badge), is_10bit ? "AVC 10-BIT" : "AVC / H.264");
                } else if (strcasecmp(cname, "av1") == 0) {
                    snprintf(codec_badge, sizeof(codec_badge), is_10bit ? "AV1 10-BIT" : "AV1");
                } else if (strcasecmp(cname, "vp9") == 0) {
                    snprintf(codec_badge, sizeof(codec_badge), is_10bit ? "VP9 10-BIT" : "VP9");
                } else {
                    snprintf(codec_badge, sizeof(codec_badge), "%s", cname);
                }
            }

            if (evo_pb_video_fps() > 1.0) {
                snprintf(fps_badge, sizeof(fps_badge), "%d FPS", (int)round(evo_pb_video_fps()));
            }
        }

        const char *audio_name = (audio_ctx && audio_ctx->codec && audio_ctx->codec->name)
                                     ? audio_ctx->codec->name
                                     : "Audio";
        const char *sub_name = (prospero_subtitle_enabled)
                                   ? "Active"
                                   : "None";

        evo_playback_osd_params_t p;
        memset(&p, 0, sizeof(p));
        p.title = title[0] ? title : "Video Playback";
        p.metadata = metadata;
        p.res_badge = res_badge;
        p.hdr_badge = hdr_badge;
        p.codec_badge = codec_badge;
        p.fps_badge = fps_badge;
        p.audio_badge = audio_badge;
        p.position_sec = display_position;
        p.duration_sec = media_duration_sec;
        p.percentage = percentage;
        p.paused = player_paused;
        p.scrub_active = prospero_scrub_active;
        p.scrub_target = prospero_scrub_target;
        p.audio_track = audio_name;
        p.sub_track = sub_name;
        p.view_mode = video_view_mode;
        p.show_stats = show_stats_for_nerds;
        p.alpha = alpha;

        if (evo_rmlui_is_initialized()) {
            evo_rmlui_update_playback_params(&p);
            evo_rmlui_render_playback_osd(fb, WIDTH, HEIGHT);
        }
    }



    /* PROSPERO_SRT_DRAW_CALL_START */

    double subtitle_position =
        resume_base_offset_seconds +
        (
            audio_ctx &&
            audio_handle >= 1
                ? audio_clock_seconds
                : evo_pb_video_clock_s()
        );

    if (subtitle_position < 0.0) {
        subtitle_position = 0.0;
    }

    prospero_subtitle_draw(
        fb,
        subtitle_position,
        osd_visibility
    );

    /* PROSPERO_SRT_DRAW_CALL_END */

    /*
     * PROSPERO_STATS_V2_START
     * Detailed playback and queue-health panel.
     */
    /*
     * PROSPERO_STATS_OPTIONS_ONLY_FIX
     * The Options button alone controls the visible statistics card.
     * Developer Mode remains available for logs and diagnostics.
     */
    if (show_stats_for_nerds) {
        char video_codec[64] = "NONE";
        char audio_codec[64] = "NONE";
        char audio_language[32] = "UND";

        int video_width = current_metadata.width;
        int video_height = current_metadata.height;
        int audio_channels = 0;
        int audio_rate = detected_audio_rate;

        if (
            play_fmt &&
            video_stream_index >= 0 &&
            video_stream_index <
                (int)play_fmt->nb_streams
        ) {
            AVStream *stream =
                play_fmt->streams[video_stream_index];

            if (stream && stream->codecpar) {
                snprintf(
                    video_codec,
                    sizeof(video_codec),
                    "%s",
                    avcodec_get_name(
                        stream->codecpar->codec_id
                    )
                );

                video_width =
                    stream->codecpar->width;

                video_height =
                    stream->codecpar->height;
            }
        }

        if (
            play_fmt &&
            audio_stream_index >= 0 &&
            audio_stream_index <
                (int)play_fmt->nb_streams
        ) {
            AVStream *stream =
                play_fmt->streams[audio_stream_index];

            if (stream && stream->codecpar) {
                snprintf(
                    audio_codec,
                    sizeof(audio_codec),
                    "%s",
                    avcodec_get_name(
                        stream->codecpar->codec_id
                    )
                );

                audio_channels =
                    stream->codecpar->
                        ch_layout.nb_channels;

                audio_rate =
                    stream->codecpar->sample_rate;

                const AVDictionaryEntry *language =
                    av_dict_get(
                        stream->metadata,
                        "language",
                        NULL,
                        0
                    );

                if (
                    language &&
                    language->value &&
                    language->value[0]
                ) {
                    snprintf(
                        audio_language,
                        sizeof(audio_language),
                        "%s",
                        language->value
                    );
                }
            }
        }

        int video_queue =
            packet_queue_count(
                &video_packet_queue
            );

        int audio_packet_queue_count =
            packet_queue_count(
                &audio_packet_queue
            );

        char video_line[160];
        char audio_line[160];
        char performance_line[160];
        char queue_line[160];
        char clock_line[160];
        char subtitle_line[160];

        snprintf(
            video_line,
            sizeof(video_line),
            "VIDEO  %s  /  %d X %d  /  %.3F FPS",
            video_codec,
            video_width,
            video_height,
            evo_pb_video_fps()
        );

        snprintf(
            audio_line,
            sizeof(audio_line),
            "AUDIO  %s  /  %s  /  %dCH  /  %d HZ",
            audio_codec,
            audio_language,
            audio_channels,
            audio_rate
        );

        snprintf(
            performance_line,
            sizeof(performance_line),
            "RENDER %d FPS  /  DECODE %d FPS",
            perf_render_fps,
            perf_decode_fps
        );

        snprintf(
            queue_line,
            sizeof(queue_line),
            "QUEUES  VIDEO %d/%d  /  AUDIO %d/%d  /  PCM %d",
            video_queue,
            video_packet_cap,
            audio_packet_queue_count,
            audio_packet_cap,
            audio_queue_count
        );

        snprintf(
            clock_line,
            sizeof(clock_line),
            "CLOCKS  VIDEO %.2F  /  AUDIO %.2F  /  DELTA %.3F",
            evo_pb_video_clock_s(),
            audio_clock_seconds,
            evo_pb_video_clock_s() -
                audio_clock_seconds
        );

        snprintf(
            subtitle_line,
            sizeof(subtitle_line),
            "SUBTITLES  %s  /  %s",
            prospero_subtitle_enabled
                ? "ON"
                : "OFF",
            prospero_subtitle_use_external
                ? "EXTERNAL"
                : (
                    prospero_embedded_subtitle_stream_index >= 0
                        ? "EMBEDDED"
                        : "NONE"
                )
        );

        int debug_x = 1115;
        int debug_y = 52;
        int debug_w = 735;
        int debug_h = 350;

        ui_round_asset(
            fb,
            debug_x,
            debug_y,
            debug_w,
            debug_h,
            24,
            osd_col(th->surface, 232),
            osd_col(th->accent, 170),
            osd_col(th->accent_soft, 50)
        );

        rr_text(
            fb,
            debug_x + 34,
            debug_y + 24,
            "PLAYBACK STATISTICS",
            osd_col(th->accent, 240),
            1
        );

        rr_fill(
            fb,
            debug_x + 32,
            debug_y + 68,
            debug_w - 64,
            1,
            osd_col(th->accent_soft, 75)
        );

        const char *lines[6] = {
            video_line,
            audio_line,
            subtitle_line,
            performance_line,
            queue_line,
            clock_line
        };

        for (int row = 0; row < 6; row++) {
            rr_text(
                fb,
                debug_x + 34,
                debug_y + 91 + row * 41,
                lines[row],
                row >= 4
                    ? osd_col(th->text_secondary, 220)
                    : osd_col(th->text_primary, 230),
                0
            );
        }
    }
    /* PROSPERO_STATS_V2_END */
}



