/* BROWSER_ICON_RENDERER_START */
static void rr_browser_icon(
    uint32_t *fb,
    int x,
    int y,
    int type
) {
    /* EVO: same tinting as rr_icon() - these are monochrome too. */
    const uint32_t tint = evo_theme_current()->accent;

    switch (type) {
        case 0:
            rr_img_tint(
                fb, x, y,
                BR_ICON_FOLDER_W,
                BR_ICON_FOLDER_H,
                BR_ICON_FOLDER,
                tint
            );
            break;

        case 1:
            rr_img_tint(
                fb, x, y,
                BR_ICON_VIDEO_W,
                BR_ICON_VIDEO_H,
                BR_ICON_VIDEO,
                tint
            );
            break;

        case 2:
            rr_img_tint(
                fb, x, y,
                BR_ICON_AUDIO_W,
                BR_ICON_AUDIO_H,
                BR_ICON_AUDIO,
                tint
            );
            break;

        case 3:
            rr_img_tint(
                fb, x, y,
                BR_ICON_IMAGE_W,
                BR_ICON_IMAGE_H,
                BR_ICON_IMAGE,
                tint
            );
            break;

        case 4:
            rr_img_tint(
                fb, x, y,
                BR_ICON_DOCUMENT_W,
                BR_ICON_DOCUMENT_H,
                BR_ICON_DOCUMENT,
                tint
            );
            break;

        case 5:
            rr_img_tint(
                fb, x, y,
                BR_ICON_DISC_W,
                BR_ICON_DISC_H,
                BR_ICON_DISC,
                tint
            );
            break;

        case 6:
            rr_img_tint(
                fb, x, y,
                BR_ICON_HOMEBREW_W,
                BR_ICON_HOMEBREW_H,
                BR_ICON_HOMEBREW,
                tint
            );
            break;

        case 7:
            rr_img_tint(
                fb, x, y,
                BR_ICON_ARCHIVE_W,
                BR_ICON_ARCHIVE_H,
                BR_ICON_ARCHIVE,
                tint
            );
            break;

        default:
            rr_img_tint(
                fb, x, y,
                BR_ICON_FILE_W,
                BR_ICON_FILE_H,
                BR_ICON_FILE,
                tint
            );
            break;
    }
}
