/* ---------------------------------------------------------------------------
 * EVO: video-out state trace.
 *
 * Written to a file on the stick rather than stdout, because stdout only
 * exists while something is holding the /hbldr pipe open - and the bug being
 * chased needs a controller in someone's hands, not a terminal.
 *
 * Off unless -DEVO_VO_DEBUG=1. Logs screen transitions and one line a second
 * while the player is up; nothing per frame.
 * ------------------------------------------------------------------------ */
#ifndef EVO_VO_DEBUG
#define EVO_VO_DEBUG 0
#endif

#if EVO_VO_DEBUG
static void evo_vo_trace(const char *tag)
{
    FILE *f = fopen("/mnt/usb0/evo_vo_debug.log", "a");
    if (!f) return;

    fprintf(f,
        "%8lld %-14s screen=%2d backend=%d vo=%ux%u pv=%ux%u ready=%d "
        "pending=%d k4live=%d pb_active=%d has_disp=%d paused=%d "
        "diag=%d supUI=%d | conv=%llu pub=%llu decf=%d vpkt=%d gate=%d "
        "dfps=%d rfps=%d aclk=%.2f vclk=%.2f | sub_en=%d sub_auto=%d "
        "sub_emb=%d sub_cues=%d sub_ext=%d sub_useext=%d "
        "| sdemux=%d sent=%d sblank=%d sadd=%d scid=%d srip=%d\n",
        now_ms(), tag, screen, (int)g_pp_backend,
        g_vo_w, g_vo_h, g_pp_vo.width, g_pp_vo.height, g_pp_vo_ready,
        g_pending_vo_reconfig, pp_product_k4_live(screen),
        g_pp_pb.active, pp_playback_has_display(&g_pp_pb),
        player_paused, g_4k_diag_active, g_4k_suppress_ui,
        (unsigned long long)g_pp_pb.stats.frames_converted,
        (unsigned long long)g_pp_pb.stats.frames_published,
        dbg_video_frames, dbg_video_packets,
        g_vo_decode_gate, perf_decode_fps, perf_render_fps,
        (double)audio_clock_seconds, evo_pb_video_clock_s(),
        prospero_subtitle_enabled, prospero_auto_subtitles_enabled,
        prospero_embedded_subtitle_stream_index,
        prospero_embedded_subtitle_count,
        prospero_subtitle_count, prospero_subtitle_use_external,
        dbg_sub_demuxed, dbg_sub_entered, dbg_sub_blank, dbg_sub_added,
        dbg_sub_cid, (int)AV_CODEC_ID_SUBRIP);

    fclose(f);
}
#else
#define evo_vo_trace(tag) ((void)0)
#endif

/*
 * On-screen performance readout, gated by the "DEBUG OVERLAY" settings row
 * (show_debug_overlay). Drawn last in the frame, after whichever screen
 * function populated `linear` - legacy immediate-mode or RmlUi - so one call
 * site covers every screen instead of threading a draw call through each
 * renderer separately.
 */
static void draw_fps_overlay(uint32_t *fb)
{
    char buf[32];
    const evo_theme *th;
    uint32_t bg, text_col;
    int w, h, x, y, text_y;

    if (!show_debug_overlay) return;

    th = evo_theme_current();
    bg = EVO_RGBA(0x00, 0x00, 0x00, 170);
    text_col = th ? th->text_primary : EVO_RGBA(0xFF, 0xFF, 0xFF, 255);

    snprintf(buf, sizeof(buf), "%d FPS", perf_render_fps);

    w = evo_text_w(buf, EVO_FACE_SMALL) + 24;
    h = 30;
    x = EVO_UI_W - w - 12;
    y = 12;

    evo_ui_round_rect(fb, x, y, w, h, 6, bg, bg, 0, 0, 0, 0);
    text_y = evo_text_y_centred(y, h, EVO_FACE_SMALL);
    evo_text_right(fb, x + w - 12, text_y, buf, text_col, EVO_FACE_SMALL);
}

/* Byte-copy src -> dst. Returns 1 on a complete copy, 0 otherwise (incl. no
 * src). Used only for the small text config files below. */
static int evo_copy_file(const char *src, const char *dst)
{
    FILE *in = fopen(src, "rb");
    if (!in)
        return 0;
    FILE *out = fopen(dst, "wb");
    if (!out) { fclose(in); return 0; }

    char b[4096];
    size_t n;
    int ok = 1;
    while ((n = fread(b, 1, sizeof b, in)) > 0) {
        if (fwrite(b, 1, n, out) != n) { ok = 0; break; }
    }
    fclose(in);
    if (fclose(out) != 0)
        ok = 0;
    return ok;
}

/*
 * One-time migration of the config store to its durable home (#46). Two legacy
 * locations to sweep, never overwriting a file already at the new root:
 *   - "/data/ps5_media_resume.txt" - the bare resume file every build wrote
 *     before #46 routed it through evo_data_path().
 *   - "/download0/evoplayer/*" - where the app module wrote everything while
 *     EVO_DATA_DIR was a compile-time string; that mount does not survive a
 *     relaunch, but the *current* boot can still read it once.
 */
static void evo_migrate_legacy_store(void)
{
    const char *root = evo_data_dir();   /* stable literal, safe to hold */
    char dst[512];

    snprintf(dst, sizeof dst, "%s/ps5_media_resume.txt", root);
    if (access(dst, F_OK) != 0 &&
        evo_copy_file("/data/ps5_media_resume.txt", dst))
        evo_bt("persistence: migrated ps5_media_resume.txt from /data");

#ifdef EVO_APP_MODULE
    if (strcmp(root, "/download0/evoplayer") != 0) {
        static const char *const leaves[] = {
            "evo_recent.txt", "evo_favorites.txt", "evo_last_folder.cfg",
            "evo_player_settings.cfg", "emby.conf", "ps5_media_resume.txt",
        };
        for (size_t i = 0; i < sizeof leaves / sizeof leaves[0]; i++) {
            char src[512];
            snprintf(src, sizeof src, "/download0/evoplayer/%s", leaves[i]);
            snprintf(dst, sizeof dst, "%s/%s", root, leaves[i]);
            if (access(dst, F_OK) != 0 && evo_copy_file(src, dst))
                evo_bt("persistence: migrated %s from /download0", leaves[i]);
        }
    }
#endif
}

/*
 * App data (favorites, recent, settings, last-folder, Emby config) lives under
 * evo_data_dir() so the player works with no USB stick present at all. The root
 * is resolved at runtime (see evo_data_path.h): /data/evoplayer once the app
 * sandbox is open (the payload: always), /download0/evoplayer only as a
 * pre-unjail fallback. Nothing else in the tree ever created that directory.
 */
static void evo_ensure_data_dir(void)
{
    evo_mkdir("/data");   /* payload: ensure the parent; app: no-op / EEXIST */
    evo_mkdir(evo_data_dir());

#ifdef EVO_APP_MODULE
    evo_bt("persistence: data root = %s (%s)", evo_data_dir(),
           evo_jailbreak_is_open() ? "sandbox open"
                                   : "FALLBACK - unjail not up yet");
#endif

    evo_migrate_legacy_store();

#ifdef EVO_BOOT_TRACE
    /* Exercise evo_readdir() on a directory that actually has files - the
     * browser's /mnt/usb0 is ENOENT until sandbox-unjail, so it can't. */
    {
        const char *root = evo_data_dir();
        evo_dir_t *d = evo_opendir(root);
        int n = 0;
        char first[80] = "";
        if (d) {
            struct dirent *e;
            while ((e = evo_readdir(d)) != NULL) {
                if (e->d_name[0] == '.') continue;
                if (!first[0]) snprintf(first, sizeof first, " first=%s", e->d_name);
                n++;
            }
            evo_closedir(d);
        }
        evo_bt("readdir %s: %s%d entries%s",
               root, d ? "" : "OPEN FAILED ", n, first);
    }
#endif
}

#ifdef EVO_APP_MODULE
/*
 * The boot self-unjail (evo_jailbreak_self, ~1.2s) can lose the timing race
 * with the jailbreak daemon. Config then loads from the /download0 fallback and
 * later saves would split across two roots. Once evo_jailbreak_ensure() finally
 * opens the sandbox (browser entry), re-point the data root at /data and reload
 * everything that was read at boot. Cheap - all small text files, each loader
 * clears before it reads. (#46)
 */
static void evo_persistence_rebind(void)
{
    evo_data_path_rebind();
    evo_ensure_data_dir();
    recent_load();
    favorites_load();
    evo_theme_reset();          /* re-scan themes/ under the new root */
    prospero_settings_load();   /* calls evo_theme_init() + set_by_name() */
    emby_init();
    /* Not prospero_last_folder_load() - the user has already entered the
     * browser by now; re-seeding current_path would yank them out of it. The
     * file still saves to /data and restores on the next boot. */
    evo_bt("persistence: rebound to %s after late unjail", evo_data_dir());
}
#endif

#ifdef EVO_APP_MODULE
/* Route FFmpeg's own diagnostics to the app-module notification channel -
 * the "why" behind an avformat_open_input / avcodec_open2 failure that would
 * otherwise only reach a toast (needs VideoOut) or nowhere. Rate-limited to
 * errors so it does not drown the popup during normal decode. */
static void evo_av_log_cb(void *avcl, int level, const char *fmt, va_list ap)
{
    (void)avcl;
    if (level > AV_LOG_ERROR)
        return;
    char msg[224];
    vsnprintf(msg, sizeof msg, fmt, ap);
    for (char *p = msg; *p; p++)
        if (*p == '\n' || *p == '\r') *p = ' ';
    if (!msg[0])
        return;

    /* Collapse the repeated identical lines FFmpeg emits when a 4K frame pool
     * can't allocate ("get_buffer() failed" x N). Only the first of a run
     * reaches the popup, and it carries the allocator's memory state so the
     * cause (real OOM vs bitstream) is visible in one screenshot. */
    static char last[224];
    static unsigned repeat;
    if (strcmp(msg, last) == 0) {
        if (++repeat % 60 == 0)
            pp_stage_bc("P8_AVLOG", "...(still repeating)");
        return;
    }
    snprintf(last, sizeof last, "%s", msg);
    repeat = 0;

    if (evo_alloc_map_info &&
        (strstr(msg, "buffer") || strstr(msg, "emory") || strstr(msg, "lloc"))) {
        uint64_t f = 0, sf = 0, sa = 0, fa = 0;
        evo_alloc_map_info(&f, &sf, &sa, &fa);
        char d[288];
        snprintf(d, sizeof d, "%s [flex=%llu anon=%llu fail=%llu avail=%lluM]",
                 msg, (unsigned long long)sf, (unsigned long long)sa,
                 (unsigned long long)f, (unsigned long long)(fa >> 20));
        pp_stage_bc("P8_AVLOG", d);
        return;
    }
    pp_stage_bc("P8_AVLOG", msg);
}
#endif

int main(void) {
#ifdef EVO_HAVE_BUILD_ID
    evo_bt("BUILD " EVO_BUILD_ID);   /* first thing on screen — catches a stale mount */
#endif
    evo_bt("main() entry");
    /* Route B probe BEFORE the self-unjail. The minimal sandbox_probe eboot
     * (which never unjails) decoded a frame; the full player (which unjails
     * first) can't call libSceVideodec2. The mid-run credential swap in
     * evo_jailbreak_self() is the prime suspect for poisoning
     * sceSysmoduleLoadModule. The probe uses a bundled AU, so it needs no
     * filesystem access and can run pre-unjail. */
    evo_videodec2_probe();  /* no-op unless -DEVO_VIDEODEC2_PROBE — Route B, bundled AU */
    evo_vdec_probe();       /* app module: preload libSceVideodec2 for the native decode backend
                             * (#31). MUST be here — before the self-unjail poisons sysmodule 207.
                             * No-op returning 0 on host + payload. */
    evo_agc_probe();        /* no-op unless -DEVO_AGC_PROBE. Before the unjail too — if
                             * libSceAgc behaves like libSceVideodec2 (API dead post-unjail),
                             * sceAgcInit must run first (#27). */
#if defined(EVO_APP_MODULE) && defined(EVO_AGC_PROBE)
    /* #27 GPU Step 2: arm the sceAgc NV12 present path. Gated behind
     * --agc-probe (was unconditional). render_frame / pp_agc_present_nv12 is
     * still unproven on hardware and it HANGS then crashes GTA VI 4K
     * (2026-09-03): once armed, the native decoder emits NV12 and pp_playback's
     * V8 branch routes it into pp_agc_present_nv12, whose GPU submit
     * (sceAgcDriverSubmitDcb -> sceAgcSuspendPoint) never returns. Without this
     * the V8 4K path uses the CPU converter (YUV420P, #31-proven). Under
     * --agc-probe, evo_agc_probe() above already calls pp_agc_init; this call
     * is the redundant idempotent one. MUST be pre-unjail (evo_vdec_probe). */
    pp_agc_init(1920, 1080, 0);
    evo_boot_log_flush();
#endif
    evo_jailbreak_self();   /* app module: self-unjail via the Lapy/etaHEN file-drop (no-op on payload) */
    evo_boot_log_flush();   /* sandbox open now — dump the pre-unjail probe results to USB */
    evo_avplayer_probe();   /* no-op unless -DEVO_AVPLAYER_PROBE — runs after unjail (needs /data) */
    evo_boot_log_flush();
#ifdef EVO_APP_MODULE
    av_log_set_level(AV_LOG_ERROR);
    av_log_set_callback(evo_av_log_cb);
#endif
    /* Initialize the 2MB-aligned Direct Memory Region. Sized (#6) for the 4K
     * CPU video working set so the rotate ring / pp_playback display / VO
     * linear staging come from this fixed slab instead of churning the heap. */
    evo_direct_mem_init(EVO_DIRECT_MEM_POOL_BYTES);

    /*
     * First, before anything draws or any thread starts. The glyph tables are
     * plain arrays with no lock on the read path - which is what keeps the
     * inner loop of every string cheap - so they have to be built while this
     * is still the only thread. toast() below already draws text.
     */
    evo_font_build_tables();

    evo_ensure_data_dir();

    toast("EVO Player", "Version " EVO_PLAYER_VERSION);
    recent_load();
    favorites_load();
    prospero_settings_load();

    /* EVO: UI sound engine. Safe to call before anything else audio-related;
     * it opens its own port and stays silent if that fails. */
    evo_sfx_init();

    /* EVO: load built-in themes and anything on /mnt/usb0/evo_themes. */
    evo_theme_init();
    prospero_last_folder_load();

#if defined(EVO_START_SCREEN) && EVO_START_SCREEN == SCREEN_USB_BROWSER
    /* Jumping straight to the browser skips the entry path that fills the
     * list, which otherwise renders a misleading "THIS FOLDER IS EMPTY". */
    load_usb_files();
#endif

    ffmpeg_test();

    sceUserServiceInitialize(NULL);
    scePadInit();

    int users[4] = {0};
    sceUserServiceGetLoginUserIdList(users);
    g_ps5_user_id = users[0];


    int pad = scePadOpen(users[0], 0, 0, NULL);

    if (pad < 0)
        toast("PAD OPEN FAIL", "Could not open controller");
    else
        toast("PAD OPEN OK", "Controller connected");

    /* EVO: hand the UI layer this file's text and icon renderers. Must happen
     * before the first frame; every evo_text/evo_icon call is a safe no-op
     * until it does, which would draw an empty page rather than crash. */
    evo_draw_bind(&EVO_DRAW_VTABLE);
    evo_rmlui_init(WIDTH, HEIGHT);
    evo_sync_rmlui_theme();

    /* EVO: controller feedback. Sound was already wired at the edge-detect
     * point; this adds the lightbar and gives both one semantic API. The
     * lightbar picks up the theme accent immediately. */
    evo_input_reset(&evo_pad_state);
    evo_feedback_init(pad, evo_sfx_play);

    evo_nav_reset((evo_screen_id)screen);
    evo_net_init();
    emby_init();
    avformat_network_init();

    PS5_PadData padData;
    uint32_t lastButtons = 0;
    bool running = true;

#if PP_BACKEND_ENABLED
    memset(&g_pp_vo, 0, sizeof(g_pp_vo));
    pp_playback_init(&g_pp_pb);
    if (pp_videoout_init(&g_pp_vo, WIDTH, HEIGHT, PP_PIXEL_BGRA32_TILED, 2) != 0) {
        toast("VIDEOOUT", "pp_videoout_init failed");
        evo_bt("pp_videoout_init FAILED step=%d rc=%d (10=Open 11=AllocDmem "
               "12=MapDmem 14=RegBuf2 15=malloc) -> exit(1)",
               pp_videoout_last_step, pp_videoout_last_rc);
        return 1;
    }
    g_pp_vo_ready = 1;
    pp_playback_attach_videoout(&g_pp_pb, &g_pp_vo);
    pp_playback_set_output(&g_pp_pb, WIDTH, HEIGHT, PP_ASPECT_FIT);
    uint32_t *linear = NULL;
    uint32_t pp_buf_idx = 0;
    uint32_t pp_pitch = 0;
#else
    int handle = sceVideoOutOpen(0xff, 0, 0, NULL);
    size_t memsize = 0x2000000;
    intptr_t paddr = 0;
    void* vaddr = NULL;

    sceKernelAllocateMainDirectMemory(memsize, 0x20000, 3, &paddr);
    sceKernelMapDirectMemory(&vaddr, memsize, 0x33, 0, paddr, 0x20000);

    PS5_VideoBuf vbuf[2];
    memset(vbuf, 0, sizeof(vbuf));
    vbuf[0].data = vaddr;
    vbuf[1].data = (void*)((uintptr_t)vaddr + memsize / 2);

    uint32_t *linear = malloc(WIDTH * HEIGHT * 4);

    struct kevent* queue = NULL;
    sceKernelCreateEqueue(&queue, "menu flip queue");
    sceVideoOutAddFlipEvent(queue, handle, NULL);
    sceVideoOutSetFlipRate(handle, 0);

    PS5_VideoAttr attr;
    memset(&attr, 0, sizeof(attr));
    sceVideoOutSetBufferAttribute2(&attr, 0x8000000022000000UL, 0, WIDTH, HEIGHT, 0, 0, 0);
    sceVideoOutRegisterBuffers2(handle, 0, 0, vbuf, 2, &attr, 0, NULL);
#endif

    evo_bt("boot ok - frame loop");
    for (int frame = 0; running; frame++) {
        evo_net_poll();
        evo_usb_remote_poll();   /* -DEVO_USB_REMOTE dev remote; no-op otherwise */
        if ((frame & 63) == 0)
            evo_boot_log_flush();   /* cheap no-op once drained; catches a late sandbox open */

#if PP_BACKEND_ENABLED
        /* Safe point: no buffer held — apply deferred 4K/1080 VO reconfig */
        pp_product_apply_pending_vo();

        /*
         * HARD UI RULE: non-player screens only draw on a live 1080 VO.
         * Skip the frame until restore succeeds (never 1080 UI into 4K plane).
         */
        if (screen != SCREEN_PLAYER) {
            if (!pp_product_ensure_ui_1080()) {
                usleep(3000);
                continue;
            }
        } else if (!pp_product_k4_live(screen) &&
                   (g_vo_w != 1920u || g_vo_h != 1080u)) {
            if (!pp_product_ensure_ui_1080()) {
                usleep(3000);
                continue;
            }
        }

        int idx = 0;
        uint32_t v8_idx = 0;
        uint64_t v8_fid = 0;
        int v8_presented = 0;

        /*
         * V8 4K path only when live VO is actually 3840x2160 (k4_live).
         */
#if PP_4K_V8_PRODUCT_ENABLE
        int v8_hold = 0;
        if (pp_product_k4_live(screen) &&
            g_pp_backend == PP_BACKEND_4K_V8_FUSED) {
            if (pp_playback_take_pending_present(&g_pp_pb, &v8_idx, &v8_fid)) {
                if (pp_videoout_present_pre_tiled(&g_pp_vo, v8_idx, v8_fid) == 0) {
                    static int s_v8_first_present;
                    if (!s_v8_first_present) {
                        pp_stage_bc_checkpoint("012_FIRST_FRAME_PRESENTED",
                                              "v8 pre_tiled");
                        s_v8_first_present = 1;
                    }
                    v8_presented = 1;
                }
            } else {
                v8_hold = 1;
                linear = NULL;
            }
        }
#else
        int v8_hold = 0;
        (void)v8_idx;
        (void)v8_fid;
#endif

        if (!v8_presented && !v8_hold) {
            if (screen != SCREEN_PLAYER || !pp_product_k4_live(screen)) {
                if (g_vo_w != 1920u || g_vo_h != 1080u ||
                    !g_pp_vo_ready || g_pp_vo.width != 1920u ||
                    g_pp_vo.height != 1080u) {
                    usleep(2000);
                    continue;
                }
            }
            linear = (uint32_t *)pp_videoout_acquire(&g_pp_vo, &pp_buf_idx, &pp_pitch);
            if (!linear) {
                usleep(500);
                continue;
            }
            if (screen == SCREEN_PLAYER) {
                memset(linear, 0, (size_t)g_vo_w * (size_t)g_vo_h * 4u);
            }
        } else if (v8_presented) {
            linear = NULL;
        }
#else
        int idx = frame % 2;
#endif

        memset(&padData, 0, sizeof(padData));

        if (pad >= 0 && scePadReadState(pad, &padData) == 0) {
            uint32_t pressed = padData.buttons & ~lastButtons;
            prospero_scrub_hold_update(padData.buttons);
            int prompt_button_handled = 0;

            /* EVO: semantic actions with auto-repeat. Holding a direction
             * used to do nothing at all - every list moved one item per
             * physical press, so reaching item 60 of a folder took 60
             * presses. See ui/include/evo_input.h for the repeat curve. */
            evo_input_update(&evo_pad_state, padData.buttons,
                             (uint64_t)now_ms());

            /* EVO: navigation feedback.
             *
             * Hooked at the single edge-detect point so every menu in the app
             * gets it without touching each screen's handler.
             *
             * Suppressed during playback (screen == 2): blips over a film are
             * unwanted, and it keeps the SFX port quiet while the media port
             * is doing the work that matters. */
            /* EVO: report the raw mask so button constants can be verified
             * against hardware instead of guessed. Every other constant in
             * this file matches the standard SCE layout, but L3/R3 are
             * defined as 0x20000/0x40000 where the standard is 0x2/0x4 -
             * which would explain L3 doing nothing. */
#if EVO_PAD_DEBUG
            if (pressed) {
                printf("[evo-pad] pressed=0x%08x buttons=0x%08x\n",
                       (unsigned)pressed, (unsigned)padData.buttons);
                fflush(stdout);
            }
#endif

            /* EVO: screenshot on either stick click, menus only.
             *
             * Both sticks are accepted because one observed mask cannot say
             * which stick produced it, and in the menus neither is bound to
             * anything else. Excluded during playback so it cannot collide
             * with R3 subtitle delay. */
            /* Menus: either stick. Playback: L3 only, because R3 nudges the
             * subtitle delay there. Excluding playback entirely - which is
             * what this did - made the one screen that can only be reached by
             * playing something the one screen impossible to capture, and so
             * the hardest to check. */
            if (screen != SCREEN_PLAYER) {
                if (pressed & (PS5_PAD_BUTTON_L3 | PS5_PAD_BUTTON_R3))
                    evo_screenshot_request = 1;
            } else if (pressed & PS5_PAD_BUTTON_L3) {
                evo_screenshot_request = 1;
            }

            if (evo_keyboard_is_open()) {
                evo_keyboard_update();
                if (pressed) {
                    evo_keyboard_handle_input(pressed);
                }
                goto skip_screen_input;
            }


            /*
             * Audio/haptic feedback on every edge.
             *
             * Suppressed during playback: blips over a film are unwanted, and
             * it keeps the SFX port quiet while the media port is doing the
             * work that matters.
             *
             * Screens that own a focus model (the launch grid, and every list)
             * report their own MOVE / WRAP / BOUNDARY below, which is finer
             * grained than this can be - so directions are only handled here
             * for the screens that have not been migrated yet. */
            if (pressed && screen != SCREEN_PLAYER && !evo_keyboard_is_open()) {
                if (pressed & PS5_PAD_BUTTON_CROSS) {
                    evo_feedback(EVO_FB_CONFIRM);
                } else if (pressed & PS5_PAD_BUTTON_CIRCLE) {
                    evo_feedback(EVO_FB_CANCEL);
                } else if (pressed & (PS5_PAD_BUTTON_TRIANGLE |
                                      PS5_PAD_BUTTON_SQUARE |
                                      PS5_PAD_BUTTON_OPTIONS)) {
                    evo_feedback(EVO_FB_TOGGLE);
                } else if (screen != SCREEN_MAIN_MENU &&
                           (pressed & (PS5_PAD_BUTTON_UP |
                                       PS5_PAD_BUTTON_DOWN |
                                       PS5_PAD_BUTTON_LEFT |
                                       PS5_PAD_BUTTON_RIGHT))) {
                    evo_feedback(EVO_FB_MOVE);
                }
            }

            if (pressed && screen == 2) {
                controls_last_used_ms = now_ms();
            }

            if (pressed & PS5_PAD_BUTTON_OPTIONS && screen == 2) {
                show_stats_for_nerds = !show_stats_for_nerds;
                toast("STATS", show_stats_for_nerds ? "ON" : "OFF");
            }

            if (pressed & PS5_PAD_BUTTON_SQUARE) {
                if (screen == 2) {
                    /* Media Info is a 1080 panel over the video: leave the 4K
                     * surface and hold the clock, remembering both. */
#if PP_BACKEND_ENABLED
                    pp_product_overlay_enter();
#endif
                    screen = SCREEN_MEDIA_INFO;
                } else if (screen == SCREEN_SUBTITLE_PICKER) {
                    evo_subs_cycle_size();
                } else if (screen == 1) {
                    evo_keyboard_open("SEARCH IN DIRECTORY", g_browser_search, 48, on_browser_search_submit, NULL);
                }
            }


            if (
                screen == 1 &&
                (pressed & PS5_PAD_BUTTON_TRIANGLE)
            ) {
                prospero_usb_toggle_selected_favorite();
            }

            if (
                screen == SCREEN_FAVORITES &&
                (pressed & PS5_PAD_BUTTON_TRIANGLE) &&
                favorite_count > 0
            ) {
                favorites_remove(
                    favorite_files[favorite_selected].path);
                favorites_save();
                toast("FAVORITES", "Removed");
            }

            if ((pressed & PS5_PAD_BUTTON_SQUARE) && screen == SCREEN_SURROUND_TEST) {
                surround_layout_mode = !surround_layout_mode;
                evo_feedback(EVO_FB_TOGGLE);
                toast("SPEAKER LAYOUT", surround_layout_mode ? "7.1 Surround (8 Channels)" : "5.1 Surround (6 Channels)");
            }

            if ((pressed & PS5_PAD_BUTTON_TRIANGLE) && screen == SCREEN_SURROUND_TEST) {
                evo_surround_stop();
                evo_feedback(EVO_FB_CANCEL);
                toast("SURROUND TEST", "Silenced");
            }

            if (pressed & PS5_PAD_BUTTON_TRIANGLE &&
                screen == SCREEN_TEXT_READER) {
                evo_reader_cycle_face();
            }

            if (pressed & PS5_PAD_BUTTON_TRIANGLE &&
                screen == SCREEN_SUBTITLE_PICKER) {
                evo_subs_cycle_size();
            }

            if (pressed & PS5_PAD_BUTTON_TRIANGLE && screen == 2) {
                if (prospero_music_mode) {
                    /* No video plane in music mode */
                } else {
                    video_view_mode++;
                    if (video_view_mode > 2)
                        video_view_mode = 0;
#if PP_BACKEND_ENABLED
                    prospero_apply_view_mode();
#endif
                    if (video_view_mode == 0)
                        toast("VIEW MODE", "FIT");
                    else if (video_view_mode == 1)
                        toast("VIEW MODE", "FILL");
                    else
                        toast("VIEW MODE", "STRETCH");
                }
            }

            if (screen == 2 && emby_active_item_id[0] && g_pp_pb.active) {
                int64_t cur_sec = (int64_t)prospero_media_clock_seconds();
                if (cur_sec > 0 && cur_sec - emby_last_report_sec >= 10) {
                    emby_last_report_sec = cur_sec;
                    emby_report_playback_progress(emby_active_item_id, cur_sec, (int64_t)media_duration_sec);
                }
            }

            /* EVO: evo_input_fired, not the raw edge - this is what gives
             * every list hold-to-scroll. */
            if (evo_input_fired(&evo_pad_state, EVO_ACT_DOWN)) {
                if (screen == SCREEN_TEXT_READER) {
                    /* Through evo_input_fired, so holding the stick scrolls
                     * continuously the way every list in the app does. */
                    evo_text_scroll(&g_reader_doc, +1, evo_reader_capacity());
                } else if (screen == SCREEN_SUBTITLE_PICKER) {
                    evo_feedback_for_move(
                        evo_focus_move(&evo_subs_focus, +1));
                } else if (evo_rail_focused) {
                    evo_rail_nav(+1);
                } else if (
                    screen == SCREEN_PLAYER &&
                    !prospero_scrub_active
                ) {
                    /*
                     * Opens the picker rather than stepping to the next
                     * track. Cycling reopens the file on every step, so on a
                     * disc rip with thirty-odd tracks reaching the one you
                     * want meant thirty reopens.
                     */
                    evo_subs_open();
                } else if (screen == SCREEN_MAIN_MENU) evo_launch_nav(0, +1);
                else if (screen == SCREEN_SETTINGS) evo_page_nav(&settings_selected, EVO_SETTINGS_COUNT, +1);
                else if (screen == SCREEN_SETTINGS_PLAYBACK) evo_page_nav(&settings_playback_selected, EVO_SETTINGS_PLAYBACK_COUNT, +1);
                else if (screen == SCREEN_SETTINGS_SUBTITLES) evo_page_nav(&settings_subtitles_selected, EVO_SETTINGS_SUBTITLES_COUNT, +1);
                else if (screen == SCREEN_SETTINGS_INTERFACE) evo_page_nav(&settings_interface_selected, EVO_SETTINGS_INTERFACE_COUNT, +1);
                else if (screen == SCREEN_SETTINGS_SYSTEM) evo_page_nav(&settings_system_selected, EVO_SETTINGS_SYSTEM_COUNT, +1);
                else if (screen == SCREEN_SURROUND_TEST) {
                    surround_test_selected = surround_nav_move(surround_test_selected, 1);
                    evo_feedback(EVO_FB_MOVE);
                }
                else if (screen == SCREEN_DEVELOPER_TOOLS) evo_page_nav(&evo_tools_selected, EVO_TOOL_COUNT, +1);
                else if (screen == SCREEN_EMBY_SETUP) evo_page_nav(&emby_setup_selected, EMBY_SETUP_COUNT, +1);
                else if (screen == SCREEN_EMBY_BROWSE && emby_item_count > 0) evo_page_nav(&emby_browse_selected, emby_item_count, +1);
                else if (screen == SCREEN_ABOUT_SUPPORT) evo_page_nav(&evo_about_selected, EVO_ABOUT_ROWS, +1);
                else if (screen == SCREEN_CHANGELOG) evo_page_nav(&evo_changelog_selected, EVO_CHANGELOG_RELEASE_COUNT, +1);
                else if (screen == SCREEN_PROFILE_SELECT) evo_page_nav(&profile_selected, 4, +1);
                else if (screen == SCREEN_THEME_SELECT) evo_page_nav(&theme_selected, evo_theme_count(), +1);
                else if (screen == SCREEN_RECENT_FILES && recent_file_count > 0) evo_page_nav(&recent_selected, recent_file_count, +1);
                else if (screen == SCREEN_FAVORITES && favorite_count > 0) evo_page_nav(&favorite_selected, favorite_count, +1);
                else if (screen == SCREEN_USB_BROWSER) evo_browser_nav(+1);
                else if (file_count > 0) file_selected = (file_selected + 1) % file_count;
            }

            if (evo_input_fired(&evo_pad_state, EVO_ACT_UP)) {
                if (screen == SCREEN_TEXT_READER) {
                    evo_text_scroll(&g_reader_doc, -1, evo_reader_capacity());
                } else if (screen == SCREEN_SUBTITLE_PICKER) {
                    evo_feedback_for_move(
                        evo_focus_move(&evo_subs_focus, -1));
                } else if (evo_rail_focused) {
                    evo_rail_nav(-1);
                } else if (
                    screen == SCREEN_PLAYER &&
                    !prospero_scrub_active
                ) {
                    prospero_subtitle_toggle();
                } else if (screen == SCREEN_MAIN_MENU) evo_launch_nav(0, -1);
                else if (screen == SCREEN_SETTINGS) evo_page_nav(&settings_selected, EVO_SETTINGS_COUNT, -1);
                else if (screen == SCREEN_SETTINGS_PLAYBACK) evo_page_nav(&settings_playback_selected, EVO_SETTINGS_PLAYBACK_COUNT, -1);
                else if (screen == SCREEN_SETTINGS_SUBTITLES) evo_page_nav(&settings_subtitles_selected, EVO_SETTINGS_SUBTITLES_COUNT, -1);
                else if (screen == SCREEN_SETTINGS_INTERFACE) evo_page_nav(&settings_interface_selected, EVO_SETTINGS_INTERFACE_COUNT, -1);
                else if (screen == SCREEN_SETTINGS_SYSTEM) evo_page_nav(&settings_system_selected, EVO_SETTINGS_SYSTEM_COUNT, -1);
                else if (screen == SCREEN_SURROUND_TEST) {
                    surround_test_selected = surround_nav_move(surround_test_selected, 0);
                    evo_feedback(EVO_FB_MOVE);
                }
                else if (screen == SCREEN_DEVELOPER_TOOLS) evo_page_nav(&evo_tools_selected, EVO_TOOL_COUNT, -1);
                else if (screen == SCREEN_EMBY_SETUP) evo_page_nav(&emby_setup_selected, EMBY_SETUP_COUNT, -1);
                else if (screen == SCREEN_EMBY_BROWSE && emby_item_count > 0) evo_page_nav(&emby_browse_selected, emby_item_count, -1);
                else if (screen == SCREEN_ABOUT_SUPPORT) evo_page_nav(&evo_about_selected, EVO_ABOUT_ROWS, -1);
                else if (screen == SCREEN_CHANGELOG) evo_page_nav(&evo_changelog_selected, EVO_CHANGELOG_RELEASE_COUNT, -1);
                else if (screen == SCREEN_PROFILE_SELECT) evo_page_nav(&profile_selected, 4, -1);
                else if (screen == SCREEN_THEME_SELECT) evo_page_nav(&theme_selected, evo_theme_count(), -1);
                else if (screen == SCREEN_RECENT_FILES && recent_file_count > 0) evo_page_nav(&recent_selected, recent_file_count, -1);
                else if (screen == SCREEN_FAVORITES && favorite_count > 0) evo_page_nav(&favorite_selected, favorite_count, -1);
                else if (screen == SCREEN_USB_BROWSER) evo_browser_nav(-1);
                else if (file_count > 0) file_selected = (file_selected + file_count - 1) % file_count;
            }

            if (evo_input_fired(&evo_pad_state, EVO_ACT_LEFT)) {
                if (screen == SCREEN_SURROUND_TEST) {
                    if (surround_test_selected >= 5) {
                        surround_test_selected = surround_nav_move(surround_test_selected, 2);
                        evo_feedback(EVO_FB_MOVE);
                    } else if (!evo_rail_focused) {
                        evo_rail_focused = 1;
                        evo_rail_index   = (int)evo_screen_section(
                                                (evo_screen_id)screen);
                        if (evo_rail_index < 0) evo_rail_index = 0;
                        evo_feedback(EVO_FB_OPEN);
                    }
                } else if (screen == SCREEN_SUBTITLE_PICKER) {
                    evo_subs_step_size(-1);
                } else if (screen == SCREEN_PLAYER) {
                    prospero_scrub_move(-10.0);
                } else if (screen == SCREEN_MAIN_MENU) {
                    evo_launch_nav_left();
                } else if (evo_section_for_screen_visible(screen) &&
                           !evo_rail_focused) {
                    /* EVO: LEFT out of the content column opens the rail.
                     * This is the one gesture that makes the sections
                     * reachable from each other - before, every section was
                     * a dead end you had to back out of to leave. */
                    evo_rail_focused = 1;
                    evo_rail_index   = (int)evo_screen_section(
                                            (evo_screen_id)screen);
                    if (evo_rail_index < 0) evo_rail_index = 0;
                    evo_feedback(EVO_FB_OPEN);
                }
            }

            if (evo_input_fired(&evo_pad_state, EVO_ACT_RIGHT)) {
                if (screen == SCREEN_SURROUND_TEST) {
                    if (evo_rail_focused) {
                        evo_rail_focused = 0;
                        evo_feedback(EVO_FB_CANCEL);
                    } else {
                        surround_test_selected = surround_nav_move(surround_test_selected, 3);
                        evo_feedback(EVO_FB_MOVE);
                    }
                } else if (screen == SCREEN_SUBTITLE_PICKER) {
                    evo_subs_step_size(+1);
                } else if (screen == SCREEN_PLAYER) {
                    prospero_scrub_move(10.0);
                } else if (evo_rail_focused) {
                    /* Ahead of the per-screen cases: on the home screen RIGHT
                     * moved the shelf cursor instead of closing the rail, so
                     * the rail could be opened and not dismissed. */
                    evo_rail_focused = 0;
                    evo_feedback(EVO_FB_CANCEL);
                } else if (screen == SCREEN_MAIN_MENU) {
                    evo_launch_nav(+1, 0);
                }
            }

            if (
                screen == SCREEN_PLAYER &&
                !prospero_scrub_active &&
                (pressed & PS5_PAD_BUTTON_R2)
            ) {
                prospero_audio_cycle_track();
            }

            /* EVO: alphabetical jump in the browser. The triggers are free
             * there, and holding a direction through 200 files is not a way
             * to find one you can already name. */
            if (screen == SCREEN_USB_BROWSER &&
                evo_input_fired(&evo_pad_state, EVO_ACT_SHOULDER_L))
                evo_browser_jump_letter(-1);

            if (screen == SCREEN_USB_BROWSER &&
                evo_input_fired(&evo_pad_state, EVO_ACT_SHOULDER_R))
                evo_browser_jump_letter(+1);

            /*
             * The triggers jump a tenth of the document, which is the reader's
             * equivalent of the browser's A-Z jump on the same buttons: the
             * control that crosses a long file in a few presses rather than a
             * few hundred.
             */
            if (screen == SCREEN_TEXT_READER &&
                evo_input_fired(&evo_pad_state, EVO_ACT_SHOULDER_L))
                evo_text_scroll(&g_reader_doc,
                                -(g_reader_doc.line_count / 10 + 1),
                                evo_reader_capacity());

            if (screen == SCREEN_TEXT_READER &&
                evo_input_fired(&evo_pad_state, EVO_ACT_SHOULDER_R))
                evo_text_scroll(&g_reader_doc,
                                +(g_reader_doc.line_count / 10 + 1),
                                evo_reader_capacity());

            /* Subtitle delay: L2 −100ms, R3 +100ms */
            if (
                screen == SCREEN_PLAYER &&
                !prospero_scrub_active &&
                (pressed & PS5_PAD_BUTTON_L2)
            ) {
                prospero_subtitle_nudge_delay(-100);
            }

            if (
                screen == SCREEN_PLAYER &&
                !prospero_scrub_active &&
                (pressed & PS5_PAD_BUTTON_R3)
            ) {
                prospero_subtitle_nudge_delay(+100);
            }

            /* EVO: the shoulders page through long lists in the browser. A
             * folder with two hundred files is a lot of d-pad otherwise, even
             * with auto-repeat. */
            if (evo_input_fired(&evo_pad_state, EVO_ACT_PAGE_UP)) {
                if (screen == SCREEN_TEXT_READER) {
                    /* One line of overlap: paging by the full height leaves
                     * nothing in common between the two views and makes it
                     * easy to lose the thread of a paragraph. */
                    int cap = evo_reader_capacity();
                    evo_text_scroll(&g_reader_doc, -(cap - 1), cap);
                } else if (screen == SCREEN_PLAYER) {
                    if (prospero_chapter_count > 0 && !prospero_scrub_active)
                        prospero_chapter_jump(-1);
                    else
                        prospero_scrub_move(-60.0);
                } else if (screen == SCREEN_USB_BROWSER) {
                    evo_browser_page(-1);
                }
            }

            if (evo_input_fired(&evo_pad_state, EVO_ACT_PAGE_DOWN)) {
                if (screen == SCREEN_TEXT_READER) {
                    int cap = evo_reader_capacity();
                    evo_text_scroll(&g_reader_doc, +(cap - 1), cap);
                } else if (screen == SCREEN_PLAYER) {
                    if (prospero_chapter_count > 0 && !prospero_scrub_active)
                        prospero_chapter_jump(+1);
                    else
                        prospero_scrub_move(60.0);
                } else if (screen == SCREEN_USB_BROWSER) {
                    evo_browser_page(+1);
                }
            }

            if (
                screen == SCREEN_SUBTITLE_PICKER &&
                (pressed & PS5_PAD_BUTTON_CROSS)
            ) {
                evo_subs_activate();
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_SUBTITLE_PICKER &&
                (pressed & PS5_PAD_BUTTON_CIRCLE)
            ) {
#if PP_BACKEND_ENABLED
                pp_product_overlay_leave();
#endif
                screen = SCREEN_PLAYER;
                controls_last_used_ms = now_ms();
                prompt_button_handled = 1;
            }

            /*
             * The stop-playback prompt. CIRCLE - the button that opened it -
             * dismisses it, so a double press goes back to the film rather
             * than through the prompt and out of the file.
             */
            if (
                screen == SCREEN_EXIT_CONFIRM &&
                (pressed & PS5_PAD_BUTTON_CIRCLE)
            ) {
#if PP_BACKEND_ENABLED
                /* Re-base the clock and put a 4K surface back before the
                 * decode thread wakes up. */
                pp_product_overlay_leave();
#endif
                screen = SCREEN_PLAYER;
                controls_last_used_ms = now_ms();
                evo_feedback(EVO_FB_CANCEL);
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_EXIT_CONFIRM &&
                (pressed & PS5_PAD_BUTTON_CROSS)
            ) {
                /* Identical to what CIRCLE on the player used to do outright,
                 * including writing the resume position before the decoder
                 * goes away. */
                recent_update_current_position();
                if (emby_active_item_id[0]) {
                    emby_report_playback_stop(emby_active_item_id, (int64_t)prospero_media_clock_seconds());
                    emby_active_item_id[0] = '\0';
                }
                stop_video_playback();

                screen = g_playback_return_screen;

                /* The browser can be returned to without ever having been
                 * populated - playback started from the launch screen. */
                if (screen == SCREEN_USB_BROWSER && file_count <= 0)
                    load_usb_files();

                evo_feedback(EVO_FB_CONFIRM);
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_PLAYER &&
                prospero_scrub_active &&
                (pressed & PS5_PAD_BUTTON_CROSS)
            ) {
                prospero_scrub_confirm();
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_PLAYER &&
                prospero_scrub_active &&
                (pressed & PS5_PAD_BUTTON_CIRCLE)
            ) {
                prospero_scrub_cancel();
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_PLAYBACK_FINISHED &&
                (pressed & PS5_PAD_BUTTON_CROSS)
            ) {
                prospero_playback_finished_replay();
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_PLAYBACK_FINISHED &&
                (pressed & PS5_PAD_BUTTON_TRIANGLE)
            ) {
                prospero_playback_finished_next();
                prompt_button_handled = 1;
            }

            if (
                screen == SCREEN_PLAYBACK_FINISHED &&
                (pressed & PS5_PAD_BUTTON_CIRCLE)
            ) {
                prospero_playback_finished_back();
                prompt_button_handled = 1;
            }

            if (screen == 4 && (pressed & PS5_PAD_BUTTON_CROSS)) {
                resume_prompt_active = 0;
                requested_resume_seek_pos = pending_resume_pos;
                resume_base_offset_seconds = pending_resume_pos;
                screen = 2;
                start_video_playback(pending_resume_path);
                toast("RESUME", "Resuming");
                prompt_button_handled = 1;
            } else if (screen == 4 && (pressed & PS5_PAD_BUTTON_CIRCLE)) {
                resume_prompt_active = 0;
                pending_resume_pos = 0.0;
                requested_resume_seek_pos = 0.0;
                resume_base_offset_seconds = 0.0;
                remove(RESUME_FILE);
                screen = 2;
                start_video_playback(pending_resume_path);
                toast("RESUME", "Starting over");
                prompt_button_handled = 1;
            } else if (
                !prompt_button_handled &&
                (pressed & PS5_PAD_BUTTON_CROSS)
            ) {
                if (evo_rail_focused) {
                    evo_rail_activate();
                } else if (screen == SCREEN_SETTINGS) {
                    prospero_settings_activate_selected();
                } else if (screen == SCREEN_SETTINGS_PLAYBACK) {
                    settings_playback_activate();
                } else if (screen == SCREEN_SETTINGS_SUBTITLES) {
                    settings_subtitles_activate();
                } else if (screen == SCREEN_SETTINGS_INTERFACE) {
                    settings_interface_activate();
                } else if (screen == SCREEN_SETTINGS_SYSTEM) {
                    settings_system_activate();
                } else if (screen == SCREEN_SURROUND_TEST) {
                    surround_test_activate();
                } else if (screen == SCREEN_PROFILE_SELECT) {
                    current_profile =
                        (PlaybackProfile)profile_selected;

                    prospero_settings_save();

                    toast(
                        "PROFILE",
                        profile_name(current_profile)
                    );

                    screen = SCREEN_SETTINGS_PLAYBACK;
                } else if (screen == SCREEN_THEME_SELECT) {
                    int count = evo_theme_count();
                    if (theme_selected >= 0 && theme_selected < count) {
                        evo_theme_set(theme_selected);
                        evo_sync_rmlui_theme();
                        prospero_settings_save();
                        evo_feedback(EVO_FB_CONFIRM);
                        toast("THEME", evo_theme_name(theme_selected));
                    }
                    screen = SCREEN_SETTINGS_INTERFACE;
                } else if (screen == SCREEN_RECENT_FILES) {
                    g_playback_return_screen = SCREEN_RECENT_FILES;
                    if (recent_file_count > 0) {
                        snprintf(current_media_path, sizeof(current_media_path), "%s", recent_files[recent_selected].path);
                        requested_resume_seek_pos = recent_files[recent_selected].last_pos;
                        resume_base_offset_seconds = recent_files[recent_selected].last_pos;
                        screen = 2;
                        start_video_playback(current_media_path);
                    }
                } else if (screen == SCREEN_FAVORITES) {
                    g_playback_return_screen = SCREEN_FAVORITES;
                    if (favorite_count > 0) {
                        snprintf(current_media_path, sizeof(current_media_path), "%s", favorite_files[favorite_selected].path);
                        requested_resume_seek_pos = 0.0;
                        resume_base_offset_seconds = 0.0;
                        screen = 2;
                        start_video_playback(current_media_path);
                    }
                } else if (screen == SCREEN_DEVELOPER_TOOLS) {
                    evo_tools_activate();
                } else if (screen == SCREEN_EMBY_SETUP) {
                    evo_emby_setup_activate();
                } else if (screen == SCREEN_EMBY_BROWSE) {
                    evo_emby_browse_activate();
                } else if (screen == SCREEN_ABOUT_SUPPORT) {
                    /* Only the changelog row goes anywhere; the other five
                     * state facts and CROSS on them should do nothing rather
                     * than feel broken. */
                    if (evo_about_selected == EVO_ABOUT_ROW_CHANGELOG) {
                        evo_changelog_selected = 0;
                        screen = SCREEN_CHANGELOG;
                        evo_feedback(EVO_FB_CONFIRM);
                    }
                } else if (screen == 2) {
                    player_paused = !player_paused;
#if PP_BACKEND_ENABLED
                    if (player_paused)
                        pp_playback_pause(&g_pp_pb);
                    else
                        pp_playback_resume(&g_pp_pb);
#endif
                    controls_last_used_ms = now_ms();
                    toast("PLAYBACK", player_paused ? "Paused" : "Playing");
                } else if (screen == 1) {
                    /* Opening a file from the browser: record where we were,
                     * so CIRCLE out of playback comes back here. */
                    g_playback_return_screen = SCREEN_USB_BROWSER;
                    enter_selected_usb();
                } else if (screen == SCREEN_MAIN_MENU) {
                    /* EVO: the launch screen is a two-dimensional grid now,
                     * so "which of six rows is selected" no longer describes
                     * the cursor. It resolves its own target. */
                    evo_launch_activate();
                }
            }

            if (!prompt_button_handled && (pressed & PS5_PAD_BUTTON_CIRCLE) && screen != 4) {
                if (evo_rail_focused) {
                    /* Close the rail first; Back should not leave the section
                     * while an overlay is open on top of it. */
                    evo_rail_focused = 0;
                } else if (screen == SCREEN_TEXT_READER) {
                    evo_reader_close();
                } else if (screen == SCREEN_PROFILE_SELECT) {
                    screen = SCREEN_SETTINGS_PLAYBACK;
                } else if (screen == SCREEN_THEME_SELECT) {
                    screen = SCREEN_SETTINGS_INTERFACE;
                } else if (screen == SCREEN_SURROUND_TEST) {
                    evo_surround_stop();
                    screen = SCREEN_SETTINGS_PLAYBACK;
                } else if (screen == SCREEN_SETTINGS_PLAYBACK ||
                           screen == SCREEN_SETTINGS_SUBTITLES ||
                           screen == SCREEN_SETTINGS_INTERFACE ||
                           screen == SCREEN_SETTINGS_SYSTEM ||
                           screen == SCREEN_DEVELOPER_TOOLS) {
                    screen = SCREEN_SETTINGS;
                } else if (screen == SCREEN_SETTINGS) {
                    screen = 0;
                } else if (screen == SCREEN_RECENT_FILES) {
                    screen = 0;
                } else if (screen == SCREEN_FAVORITES) {
                    screen = 0;
                } else if (screen == SCREEN_ABOUT_SUPPORT) {
                    screen = 0;
                } else if (screen == SCREEN_CHANGELOG) {
                    /* Back to About, not to the launch screen - the changelog
                     * is only reachable from there. */
                    screen = SCREEN_ABOUT_SUPPORT;
                } else if (screen == SCREEN_DEVELOPER_TOOLS) {
                    screen = SCREEN_SETTINGS;
                } else if (screen == SCREEN_EMBY_SETUP) {
                    screen = 0;
                } else if (screen == SCREEN_EMBY_BROWSE) {
                    evo_emby_browse_back();
                } else if (screen == SCREEN_MEDIA_INFO) {
#if PP_BACKEND_ENABLED
                    pp_product_overlay_leave();
#endif
                    screen = 2;
                } else if (screen == 3) {
                    screen = 1;
                } else if (screen == 2) {
                    /*
                     * Ask first. Tearing down the decoder, the audio port and
                     * your position in the file is the one irreversible thing
                     * CIRCLE does anywhere in the app, and it did it on a
                     * single press of the same button that means "back" on
                     * every other screen.
                     *
                     * Where it returns to is decided when the prompt is
                     * accepted, not here - see SCREEN_EXIT_CONFIRM above.
                     */
#if PP_BACKEND_ENABLED
                    /*
                     * Same overlay treatment Media Info gets, and for the same
                     * reason: leaving `screen` off SCREEN_PLAYER already
                     * stalls the decode thread, but the presentation clock's
                     * wall-time base keeps running, so on cancel every
                     * arriving frame looks late by however long the prompt was
                     * up and gets dropped. That is the 0.1.3 freeze, and it
                     * would have come straight back here.
                     */
                    pp_product_overlay_enter();
#endif
                    screen = SCREEN_EXIT_CONFIRM;
                    controls_last_used_ms = now_ms();
                    evo_feedback(EVO_FB_OPEN);
                } else if (screen == 1) {
                    if (g_browser_search[0] != '\0') {
                        g_browser_search[0] = '\0';
                        load_usb_files();
                        file_selected = 0;
                        file_scroll   = 0;
                        evo_browser_sync();
                        evo_feedback(EVO_FB_CANCEL);
                        toast("SEARCH", "Filter cleared");
                    } else {
                        usb_go_back();
                    }
                } else {

                    toast("EXIT", "Use PS button to close for now");
                }
            }

skip_screen_input:
            lastButtons = padData.buttons;
        }

        /* EVO: let the lightbar's confirm flash decay back to the resting
         * accent. Must run every frame regardless of input. */
        evo_feedback_tick((uint64_t)now_ms());

        if (screen == 2 && !player_paused) {
            player_elapsed++;
        }

        prospero_playback_finished_update();

#if EVO_VO_DEBUG
        {
            static int       last_screen = -1;
            static long long last_tick;

            if (screen != last_screen) {
                evo_vo_trace(last_screen < 0 ? "start" : "screen-change");
                last_screen = screen;
            } else if (screen == SCREEN_PLAYER &&
                       now_ms() - last_tick >= 1000) {
                evo_vo_trace("player-tick");
                last_tick = now_ms();
            }
        }
#endif

#if PP_BACKEND_ENABLED
        /*
         * After stop / leave-player while VO is still 4K: do not draw 1080 UI
         * into the 4K plane (one-frame stacked flash). Drop the buffer; next
         * frame top-of-loop applies 1080 and redraws cleanly.
         */
        if (linear && screen != SCREEN_PLAYER &&
            (g_vo_w != 1920u || g_vo_h != 1080u || g_pending_vo_reconfig)) {
            pp_videoout_release(&g_pp_vo, pp_buf_idx);
            linear = NULL;
            v8_hold = 1;
        }
#endif

        /* V8 direct present: video already on screen; skip UI composite this frame. */
        if (linear) {
        if (screen == 2 && pp_product_k4_live(screen)) {
            /*
             * Native UHD VO: draw_player_screen is 1080-only and would only
             * paint the top-left of a 4K buffer (choppy/wrong). Copy full VO
             * plane from the convert path (V3 letterbox or full).
             */
            if (g_pp_pb.active && pp_playback_has_display(&g_pp_pb)) {
                (void)pp_playback_copy_display(
                    &g_pp_pb, linear, g_vo_w * 4u, g_vo_w, g_vo_h);
            }
            {
                static int s_noui_bc;
                if (!s_noui_bc) {
                    pp_stage_bc_checkpoint("012B_UHD_FULL_PLANE_PRESENT",
                                          pp_4k_stage_name(PP_4K_PRODUCT_STAGE));
                    s_noui_bc = 1;
                }
            }
        } else if (screen == 2 && g_4k_diag_active && g_4k_suppress_ui) {
            if (g_pp_pb.active && pp_playback_has_display(&g_pp_pb)) {
                (void)pp_playback_copy_display(
                    &g_pp_pb, linear, g_vo_w * 4u, g_vo_w, g_vo_h);
            }
        } else if (screen == 0)
            draw_menu_linear(linear);
        else if (screen == 1)
            draw_usb_browser(linear);
        else if (screen == 2)
            draw_player_screen(linear);
        else if (screen == 3)
            draw_image_screen(linear);
        else if (screen == 4)
            draw_resume_prompt(linear);
        else if (screen == SCREEN_SETTINGS)
            draw_settings_screen(linear);
        else if (screen == SCREEN_SETTINGS_PLAYBACK)
            draw_settings_playback_screen(linear);
        else if (screen == SCREEN_SETTINGS_SUBTITLES)
            draw_settings_subtitles_screen(linear);
        else if (screen == SCREEN_SETTINGS_INTERFACE)
            draw_settings_interface_screen(linear);
        else if (screen == SCREEN_SETTINGS_SYSTEM)
            draw_settings_system_screen(linear);
        else if (screen == SCREEN_SURROUND_TEST)
            draw_surround_test_screen(linear);
        else if (screen == SCREEN_PROFILE_SELECT)
            draw_profile_screen(linear);
        else if (screen == SCREEN_THEME_SELECT)
            draw_theme_select_screen(linear);
        else if (screen == SCREEN_RECENT_FILES)
            draw_recent_files_screen(linear);
        else if (screen == SCREEN_FAVORITES)
            draw_favorites_screen(linear);
        else if (screen == SCREEN_ABOUT_SUPPORT)
            draw_about_support_screen(linear);
        else if (screen == SCREEN_CHANGELOG)
            draw_changelog_screen(linear);
        else if (screen == SCREEN_TEXT_READER)
            draw_text_reader_screen(linear);
        else if (screen == SCREEN_DEVELOPER_TOOLS)
            draw_developer_tools_screen(linear);
        else if (screen == SCREEN_EMBY_SETUP)
            draw_emby_setup_screen(linear);
        else if (screen == SCREEN_EMBY_BROWSE)
            draw_emby_browse_screen(linear);
        else if (screen == SCREEN_MEDIA_INFO)
            draw_media_info_screen(linear);
        else if (screen == SCREEN_SUBTITLE_PICKER) {
            /*
             * The film keeps playing underneath. Deliberately not paused:
             * pausing to choose a subtitle track means the first thing the
             * new track has to do is catch up, and pausing around a screen
             * change is exactly what desynced the presentation clock in the
             * media-info freeze.
             */
            draw_player_screen(linear);
            draw_subtitle_picker(linear);
        }
        else if (screen == SCREEN_EXIT_CONFIRM) {
            /* Over the player, for the same reason the picker is: the frame
             * behind the panel is what makes the prompt read as "this is
             * still playing" rather than as "this has already stopped". */
            draw_player_screen(linear);
            draw_exit_confirm_screen(linear);
        }
        else if (screen == SCREEN_PLAYBACK_FINISHED) {
            /* Wait one frame if 1080 restore still pending */
            if (g_vo_w == 1920u && g_vo_h == 1080u)
                draw_playback_finished_screen(linear);
            else {
                /* fill black until VO is 1080 */
                size_t n = (size_t)g_vo_w * (size_t)g_vo_h;
                for (size_t i = 0; i < n; i++)
                    linear[i] = 0xFF000000u;
            }
        }
        else
            draw_menu_linear(linear);

        /* Virtual Keyboard modal overlay */
        if (evo_keyboard_is_open())
            evo_screen_keyboard(linear);

        /* Toasts only when UI allowed (or menus); stage 1-3 video-only skips toast draw */
        if (!(screen == 2 && g_4k_diag_active && g_4k_suppress_ui))
            draw_prospero_toast(linear);

        draw_fps_overlay(linear);

        /* EVO: screenshot. Taken here, after everything has been drawn into
         * the linear staging buffer but before it is swizzled and flipped,
         * so the capture is exactly what reaches the panel. */
        /* EVO: auto-capture N seconds after start, for iterating on the UI
         * without needing someone at the controller. Build with
         * -DEVO_AUTOSHOT=<seconds>. Off in normal builds. */
#if EVO_AUTOSHOT
        {
            static int autoshot_done = 0;
            static uint64_t autoshot_t0 = 0;
            uint64_t nowms = now_ms();
            if (!autoshot_t0) autoshot_t0 = nowms;
            if (!autoshot_done && nowms - autoshot_t0 > (EVO_AUTOSHOT * 1000ull)) {
                autoshot_done = 1;
                evo_screenshot_request = 1;
            }
        }
#endif

        if (evo_screenshot_request) {
            evo_screenshot_request = 0;
            if (evo_screenshot_write(linear, (int)g_vo_w, (int)g_vo_h) == 0)
                toast("SCREENSHOT", "SAVED TO USB");
            else
                toast("SCREENSHOT", "SAVE FAILED");
        }
        } /* if (linear) */

#if PP_BACKEND_ENABLED
        (void)idx;
        if (!v8_presented && !v8_hold) {
            if (pp_videoout_present(&g_pp_vo, pp_buf_idx, (uint64_t)frame) != 0) {
                /* present failed; buffer already released by backend */
            }
        } else if (v8_hold) {
            /* Light sleep so we don't spin at kHz while holding last V8 frame */
            usleep(2000);
        }
#else
        PS5_DrawPixelsAsTiles(linear, (uint32_t*)vbuf[idx].data, WIDTH, HEIGHT);

        sceVideoOutSubmitFlip(handle, idx, 1, frame);
#endif

        perf_render_frames++;
        {
            long long pm = perf_now_ms();
            if (perf_last_ms == 0)
                perf_last_ms = pm;
            if (pm - perf_last_ms >= 1000) {
                perf_render_fps = perf_render_frames;
                perf_decode_fps = perf_decode_frames;
#if EVO_DIAG_FPS
                printf("[evo-diag] screen=%d fps=%d\n", screen, perf_render_fps);
                fflush(stdout);
#endif
                perf_render_frames = 0;
                perf_decode_frames = 0;
                perf_last_ms = pm;
            }
        }
        /*
         * UI menus are synchronized to hardware VSYNC via pp_videoout_acquire /
         * sceVideoOutSubmitFlip at 60 Hz. Do not add artificial multi-millisecond
         * sleeps in menu mode, which causes missed VSYNC deadlines and frame drops.
         */
        if (screen == SCREEN_PLAYER)
            usleep(250);
    }

#if PP_BACKEND_ENABLED
    stop_video_playback();
    /* Restore 1080 VO for clean exit if still on 4K */
    if (g_vo_w != 1920u || g_vo_h != 1080u)
        (void)pp_product_reconfigure_vo(1920, 1080, 2);
    pp_playback_shutdown(&g_pp_pb);
    if (g_pp_vo_ready)
        pp_videoout_shutdown(&g_pp_vo);
#endif

    return 0;
}
